/// <reference types="tree-sitter-cli/dsl" />
// @ts-check

/**
 * Tree-sitter grammar for CodeYourPCB DSL
 *
 * Syntax overview:
 *   version 1
 *   board name { size WxH, layers N }
 *   component REFDES type "footprint" { value "V", at X,Y }
 *   net NAME { pin.refs }
 */
module.exports = grammar({
  name: 'cypcb',

  // Whitespace and comments can appear anywhere
  extras: $ => [
    /\s/,
    $.line_comment,
    $.block_comment,
  ],

  // Reserved words for keyword optimization
  word: $ => $.identifier,

  rules: {
    // Entry point: optional version followed by definitions
    source_file: $ => seq(
      optional($.version_statement),
      repeat($._definition),
    ),

    // version 1
    version_statement: $ => seq(
      'version',
      field('number', $.number),
    ),

    // Top-level definitions
    _definition: $ => choice(
      $.board_definition,
      $.component_definition,
      $.net_definition,
      $.footprint_definition,
      $.zone_definition,
      $.trace_definition,
    ),

    // board name { properties }
    board_definition: $ => seq(
      'board',
      field('name', $.identifier),
      '{',
      repeat($.board_property),
      '}',
    ),

    board_property: $ => choice(
      $.size_property,
      $.layers_property,
      $.stackup_property,
    ),

    // size 30mm x 20mm
    size_property: $ => seq(
      'size',
      field('width', $.dimension),
      'x',
      field('height', $.dimension),
    ),

    // layers 2
    layers_property: $ => seq(
      'layers',
      field('count', $.number),
    ),

    // stackup { ... } (placeholder for future)
    stackup_property: $ => seq(
      'stackup',
      '{',
      repeat($.stackup_layer),
      '}',
    ),

    stackup_layer: $ => seq(
      field('layer_type', choice('copper', 'prepreg', 'core', 'mask', 'silk')),
      optional(field('thickness', $.dimension)),
    ),

    // component R1 resistor "0402" { ... }
    component_definition: $ => seq(
      'component',
      field('refdes', $.identifier),
      field('type', $.component_type),
      field('footprint', $.string),
      '{',
      repeat($._component_property),
      '}',
    ),

    component_type: $ => choice(
      'resistor',
      'capacitor',
      'inductor',
      'ic',
      'led',
      'connector',
      'diode',
      'transistor',
      'crystal',
      'generic',
    ),

    _component_property: $ => choice(
      $.value_property,
      $.position_property,
      $.rotation_property,
      $.net_assignment,
    ),

    // value "330"
    value_property: $ => seq(
      'value',
      field('value', $.string),
    ),

    // at 10mm, 8mm
    position_property: $ => seq(
      'at',
      field('x', $.dimension),
      ',',
      field('y', $.dimension),
    ),

    // rotate 90 (or rotate 90deg, rotate 90degrees)
    rotation_property: $ => seq(
      'rotate',
      field('angle', $.number),
      optional(field('unit', choice('deg', 'degrees'))),
    ),

    // pin.1 = NET_NAME (inline net assignment in component)
    net_assignment: $ => seq(
      field('pin', $.pin_identifier),
      '=',
      field('net', $.identifier),
    ),

    // net VCC { J1.1, R1.1 }
    net_definition: $ => seq(
      'net',
      field('name', $.identifier),
      optional($.net_constraint_block),
      '{',
      optional($.pin_ref_list),
      '}',
    ),

    // Optional constraint block: net VCC [width 0.3mm] { ... }
    net_constraint_block: $ => seq(
      '[',
      repeat($.net_constraint),
      ']',
    ),

    net_constraint: $ => choice(
      $.width_constraint,
      $.clearance_constraint,
      $.current_constraint,
    ),

    // width 0.3mm
    width_constraint: $ => seq(
      'width',
      field('value', $.dimension),
    ),

    // clearance 0.2mm
    clearance_constraint: $ => seq(
      'clearance',
      field('value', $.dimension),
    ),

    // current 500mA or current 2A
    current_constraint: $ => seq(
      'current',
      field('value', $.current_value),
    ),

    // Current value with unit (mA or A)
    current_value: $ => seq(
      field('amount', $.number),
      field('unit', $.current_unit),
    ),

    current_unit: $ => choice('mA', 'A'),

    // Comma-separated list of pin references
    pin_ref_list: $ => seq(
      $.pin_ref,
      repeat(seq(
        optional(','),
        $.pin_ref,
      )),
    ),

    // J1.1 or J1.VCC (component.pin)
    pin_ref: $ => seq(
      field('component', $.identifier),
      '.',
      field('pin', $.pin_identifier),
    ),

    // Pin can be a number or identifier (1, VCC, anode, cathode)
    pin_identifier: $ => choice(
      $.number,
      $.identifier,
    ),

    // Dimension: number with optional unit (10mm, 100mil, 1in, 1000nm, -5mm)
    dimension: $ => seq(
      optional(field('sign', '-')),
      field('value', $.number),
      optional(field('unit', $.unit)),
    ),

    // Units
    unit: $ => choice('mm', 'mil', 'in', 'nm'),

    // Terminals
    identifier: $ => /[a-zA-Z_][a-zA-Z0-9_]*/,

    // Numbers: integers or decimals
    number: $ => /\d+(\.\d+)?/,

    // Strings: double-quoted
    string: $ => seq(
      '"',
      /[^"]*/,
      '"',
    ),

    // Comments
    line_comment: $ => token(seq('//', /.*/)),

    block_comment: $ => token(seq(
      '/*',
      /[^*]*\*+([^/*][^*]*\*+)*/,
      '/',
    )),

    // footprint NAME { ... }
    footprint_definition: $ => seq(
      'footprint',
      field('name', $.identifier),
      '{',
      repeat($.footprint_property),
      '}',
    ),

    footprint_property: $ => choice(
      $.description_property,
      $.pad_definition,
      $.courtyard_property,
    ),

    // description "text"
    description_property: $ => seq(
      'description',
      field('text', $.string),
    ),

    // pad N shape at X, Y size W x H [drill D]
    pad_definition: $ => seq(
      'pad',
      field('number', $.number),
      field('shape', $.pad_shape),
      'at',
      field('x', $.dimension),
      ',',
      field('y', $.dimension),
      'size',
      field('width', $.dimension),
      'x',
      field('height', $.dimension),
      optional(field('drill', $.drill_spec)),
    ),

    drill_spec: $ => seq('drill', $.dimension),

    pad_shape: $ => choice('rect', 'circle', 'roundrect', 'oblong'),

    // courtyard W x H
    courtyard_property: $ => seq(
      'courtyard',
      field('width', $.dimension),
      'x',
      field('height', $.dimension),
    ),

    // zone NAME { ... } or keepout NAME { ... }
    zone_definition: $ => seq(
      field('kind', choice('zone', 'keepout')),
      optional(field('name', $.identifier)),
      '{',
      repeat($.zone_property),
      '}',
    ),

    zone_property: $ => choice(
      $.zone_bounds,
      $.zone_layer,
      $.zone_net,
    ),

    // bounds X1, Y1 to X2, Y2
    zone_bounds: $ => seq(
      'bounds',
      field('min_x', $.dimension),
      ',',
      field('min_y', $.dimension),
      'to',
      field('max_x', $.dimension),
      ',',
      field('max_y', $.dimension),
    ),

    // layer top | bottom | all
    zone_layer: $ => seq('layer', field('name', $.layer_name)),

    layer_name: $ => choice('top', 'bottom', 'all'),

    // net NETNAME (for copper pour zones)
    zone_net: $ => seq('net', field('net', $.identifier)),

    // ========================================================================
    // Manual Trace Definitions
    // ========================================================================

    // trace NET_NAME { from PIN to PIN [via X, Y] [layer L] [width W] [locked] }
    trace_definition: $ => seq(
      'trace',
      field('net', $.identifier),
      '{',
      repeat($._trace_property),
      '}',
    ),

    _trace_property: $ => choice(
      $.trace_from,
      $.trace_to,
      $.trace_via,
      $.trace_layer,
      $.trace_width,
      $.trace_locked,
    ),

    // from R1.1
    trace_from: $ => seq(
      'from',
      field('pin', $.pin_ref),
    ),

    // to C1.1
    trace_to: $ => seq(
      'to',
      field('pin', $.pin_ref),
    ),

    // via 5mm, 8mm (waypoint position)
    trace_via: $ => seq(
      'via',
      field('x', $.dimension),
      ',',
      field('y', $.dimension),
    ),

    // layer Top or layer Bottom
    trace_layer: $ => seq(
      'layer',
      field('name', $.trace_layer_name),
    ),

    trace_layer_name: $ => choice('Top', 'Bottom', 'Inner1', 'Inner2', 'Inner3', 'Inner4'),

    // width 0.3mm
    trace_width: $ => seq(
      'width',
      field('value', $.dimension),
    ),

    // locked (keyword only, no value)
    trace_locked: $ => 'locked',
  },
});

//! AST types for CodeYourPCB DSL.
//!
//! This module defines the typed Abstract Syntax Tree (AST) nodes that are
//! produced by converting Tree-sitter's Concrete Syntax Tree (CST).
//!
//! All AST nodes carry [`Span`] information for error reporting and
//! source mapping back to the original code.
//!
//! # Example
//!
//! A typical AST structure for:
//! ```cypcb
//! version 1
//! board test { size 30mm x 20mm }
//! ```
//!
//! Would be:
//! ```rust,ignore
//! SourceFile {
//!     version: Some(1),
//!     definitions: vec![
//!         Definition::Board(BoardDef {
//!             name: Identifier { value: "test", span: ... },
//!             size: Some(SizeProperty { width: ..., height: ... }),
//!             layers: None,
//!             ...
//!         })
//!     ],
//!     span: Span { start: 0, end: 42 },
//! }
//! ```

use cypcb_core::Unit;
use serde::{Deserialize, Serialize};

/// A byte range in the source code.
///
/// Used for error reporting and source mapping. Start and end are byte offsets
/// into the source string (inclusive start, exclusive end).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Span {
    /// Start byte offset (inclusive).
    pub start: usize,
    /// End byte offset (exclusive).
    pub end: usize,
}

impl Span {
    /// Create a new span from start and end byte offsets.
    pub const fn new(start: usize, end: usize) -> Self {
        Span { start, end }
    }

    /// Create a span that covers a single point.
    pub const fn point(pos: usize) -> Self {
        Span {
            start: pos,
            end: pos,
        }
    }

    /// Return the length of this span in bytes.
    pub const fn len(&self) -> usize {
        self.end - self.start
    }

    /// Return true if this span is empty.
    pub const fn is_empty(&self) -> bool {
        self.start >= self.end
    }

    /// Merge two spans to create a span covering both.
    pub fn merge(self, other: Span) -> Span {
        Span {
            start: self.start.min(other.start),
            end: self.end.max(other.end),
        }
    }

    /// Convert to a miette SourceSpan.
    pub fn to_miette(self) -> miette::SourceSpan {
        (self.start, self.len()).into()
    }
}

impl From<Span> for miette::SourceSpan {
    fn from(span: Span) -> Self {
        span.to_miette()
    }
}

/// The root AST node representing an entire source file.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SourceFile {
    /// Optional version declaration (e.g., `version 1`).
    pub version: Option<u32>,
    /// All top-level definitions in the file.
    pub definitions: Vec<Definition>,
    /// Span covering the entire file.
    pub span: Span,
}

/// A top-level definition in the source file.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Definition {
    /// A board definition.
    Board(BoardDef),
    /// A component definition.
    Component(ComponentDef),
    /// A net definition.
    Net(NetDef),
    /// A custom footprint definition.
    Footprint(FootprintDef),
    /// A zone definition (keepout or copper pour).
    Zone(ZoneDef),
    /// A manual trace definition.
    Trace(TraceDef),
}

impl Definition {
    /// Get the span of this definition.
    pub fn span(&self) -> Span {
        match self {
            Definition::Board(b) => b.span,
            Definition::Component(c) => c.span,
            Definition::Net(n) => n.span,
            Definition::Footprint(f) => f.span,
            Definition::Zone(z) => z.span,
            Definition::Trace(t) => t.span,
        }
    }
}

/// A board definition: `board name { ... }`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BoardDef {
    /// The board name (identifier).
    pub name: Identifier,
    /// Size property if specified.
    pub size: Option<SizeProperty>,
    /// Number of copper layers (2, 4, etc.).
    pub layers: Option<u8>,
    /// Stackup definition if specified.
    pub stackup: Option<StackupDef>,
    /// Span covering the entire board definition.
    pub span: Span,
}

/// Board size property: `size 30mm x 20mm`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SizeProperty {
    /// Board width.
    pub width: Dimension,
    /// Board height.
    pub height: Dimension,
    /// Span covering the size property.
    pub span: Span,
}

/// Stackup definition containing layer information.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StackupDef {
    /// List of layers in the stackup.
    pub layers: Vec<StackupLayer>,
    /// Span covering the stackup definition.
    pub span: Span,
}

/// A single layer in a stackup definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StackupLayer {
    /// Type of layer (copper, prepreg, etc.).
    pub layer_type: LayerType,
    /// Optional thickness of the layer.
    pub thickness: Option<Dimension>,
    /// Span covering this layer definition.
    pub span: Span,
}

/// Types of layers in a PCB stackup.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum LayerType {
    /// Copper layer for traces.
    Copper,
    /// Prepreg (pre-impregnated composite fibers).
    Prepreg,
    /// Core material.
    Core,
    /// Solder mask.
    Mask,
    /// Silkscreen.
    Silk,
}

impl LayerType {
    /// Parse a layer type from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "copper" => Some(LayerType::Copper),
            "prepreg" => Some(LayerType::Prepreg),
            "core" => Some(LayerType::Core),
            "mask" => Some(LayerType::Mask),
            "silk" => Some(LayerType::Silk),
            _ => None,
        }
    }
}

/// A component definition: `component R1 resistor "0402" { ... }`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ComponentDef {
    /// Component reference designator (R1, C1, U1, etc.).
    pub refdes: Identifier,
    /// Type of component.
    pub kind: ComponentKind,
    /// Footprint name (e.g., "0402", "SOIC-8").
    pub footprint: StringLit,
    /// Component value if specified (e.g., "10k", "100nF").
    pub value: Option<StringLit>,
    /// Position if specified.
    pub position: Option<PositionExpr>,
    /// Rotation in degrees if specified.
    pub rotation: Option<RotationExpr>,
    /// Inline net assignments (pin.1 = VCC).
    pub net_assignments: Vec<NetAssignment>,
    /// Span covering the entire component definition.
    pub span: Span,
}

/// Types of electronic components.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ComponentKind {
    /// Resistor (R prefix).
    Resistor,
    /// Capacitor (C prefix).
    Capacitor,
    /// Inductor (L prefix).
    Inductor,
    /// Integrated circuit (U prefix).
    Ic,
    /// LED (D or LED prefix).
    Led,
    /// Connector (J prefix).
    Connector,
    /// Diode (D prefix).
    Diode,
    /// Transistor (Q prefix).
    Transistor,
    /// Crystal oscillator (Y prefix).
    Crystal,
    /// Generic component.
    Generic,
}

impl ComponentKind {
    /// Parse a component kind from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "resistor" => Some(ComponentKind::Resistor),
            "capacitor" => Some(ComponentKind::Capacitor),
            "inductor" => Some(ComponentKind::Inductor),
            "ic" => Some(ComponentKind::Ic),
            "led" => Some(ComponentKind::Led),
            "connector" => Some(ComponentKind::Connector),
            "diode" => Some(ComponentKind::Diode),
            "transistor" => Some(ComponentKind::Transistor),
            "crystal" => Some(ComponentKind::Crystal),
            "generic" => Some(ComponentKind::Generic),
            _ => None,
        }
    }

    /// Get the expected reference designator prefix for this component kind.
    pub fn refdes_prefix(&self) -> &'static str {
        match self {
            ComponentKind::Resistor => "R",
            ComponentKind::Capacitor => "C",
            ComponentKind::Inductor => "L",
            ComponentKind::Ic => "U",
            ComponentKind::Led => "D",
            ComponentKind::Connector => "J",
            ComponentKind::Diode => "D",
            ComponentKind::Transistor => "Q",
            ComponentKind::Crystal => "Y",
            ComponentKind::Generic => "X",
        }
    }
}

/// Position expression: `at 10mm, 8mm`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PositionExpr {
    /// X coordinate.
    pub x: Dimension,
    /// Y coordinate.
    pub y: Dimension,
    /// Span covering the position expression.
    pub span: Span,
}

/// Rotation expression: `rotate 90` or `rotate 90deg`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RotationExpr {
    /// Rotation angle in degrees.
    pub angle: f64,
    /// Span covering the rotation expression.
    pub span: Span,
}

/// Inline net assignment: `pin.1 = VCC`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetAssignment {
    /// Pin identifier (number or name).
    pub pin: PinId,
    /// Net name to assign.
    pub net: Identifier,
    /// Span covering the assignment.
    pub span: Span,
}

/// A net definition: `net VCC { J1.1, R1.1 }`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetDef {
    /// Net name.
    pub name: Identifier,
    /// Optional constraints (width, clearance).
    pub constraints: Option<NetConstraints>,
    /// List of pin references connected to this net.
    pub connections: Vec<PinRef>,
    /// Span covering the entire net definition.
    pub span: Span,
}

/// Net constraints: `[width 0.3mm, clearance 0.2mm, current 500mA]`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetConstraints {
    /// Trace width constraint.
    pub width: Option<Dimension>,
    /// Clearance constraint.
    pub clearance: Option<Dimension>,
    /// Current carrying requirement (for IPC-2221 calculation).
    pub current: Option<CurrentValue>,
    /// Span covering the constraint block.
    pub span: Span,
}

/// Current value with unit: `500mA` or `2A`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CurrentValue {
    /// Numeric value.
    pub value: f64,
    /// Unit of current measurement.
    pub unit: CurrentUnit,
    /// Span covering the current value.
    pub span: Span,
}

impl CurrentValue {
    /// Create a new current value.
    pub fn new(value: f64, unit: CurrentUnit, span: Span) -> Self {
        CurrentValue { value, unit, span }
    }

    /// Convert to milliamps.
    pub fn to_milliamps(&self) -> f64 {
        match self.unit {
            CurrentUnit::Milliamps => self.value,
            CurrentUnit::Amps => self.value * 1000.0,
        }
    }

    /// Convert to amps.
    pub fn to_amps(&self) -> f64 {
        match self.unit {
            CurrentUnit::Milliamps => self.value / 1000.0,
            CurrentUnit::Amps => self.value,
        }
    }
}

impl std::fmt::Display for CurrentValue {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{}", self.value, self.unit)
    }
}

/// Unit of current measurement.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum CurrentUnit {
    /// Milliamps (mA).
    Milliamps,
    /// Amps (A).
    Amps,
}

impl CurrentUnit {
    /// Parse a current unit from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "mA" => Some(CurrentUnit::Milliamps),
            "A" => Some(CurrentUnit::Amps),
            _ => None,
        }
    }
}

impl std::fmt::Display for CurrentUnit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CurrentUnit::Milliamps => write!(f, "mA"),
            CurrentUnit::Amps => write!(f, "A"),
        }
    }
}

/// A pin reference: `J1.1` or `U1.VCC`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PinRef {
    /// Component reference designator.
    pub component: Identifier,
    /// Pin identifier (number or name).
    pub pin: PinId,
    /// Span covering the pin reference.
    pub span: Span,
}

/// A pin identifier: number or name.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum PinId {
    /// Numeric pin (1, 2, 3, ...).
    Number(u32),
    /// Named pin (VCC, GND, anode, cathode, ...).
    Name(String),
}

impl PinId {
    /// Create a numeric pin ID.
    pub fn number(n: u32) -> Self {
        PinId::Number(n)
    }

    /// Create a named pin ID.
    pub fn name(s: impl Into<String>) -> Self {
        PinId::Name(s.into())
    }
}

impl std::fmt::Display for PinId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PinId::Number(n) => write!(f, "{}", n),
            PinId::Name(s) => write!(f, "{}", s),
        }
    }
}

/// An identifier token.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Identifier {
    /// The identifier text.
    pub value: String,
    /// Span of the identifier.
    pub span: Span,
}

impl Identifier {
    /// Create a new identifier.
    pub fn new(value: impl Into<String>, span: Span) -> Self {
        Identifier {
            value: value.into(),
            span,
        }
    }
}

impl std::fmt::Display for Identifier {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.value)
    }
}

/// A string literal token.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StringLit {
    /// The string value (without quotes).
    pub value: String,
    /// Span of the entire string literal (including quotes).
    pub span: Span,
}

impl StringLit {
    /// Create a new string literal.
    pub fn new(value: impl Into<String>, span: Span) -> Self {
        StringLit {
            value: value.into(),
            span,
        }
    }
}

impl std::fmt::Display for StringLit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "\"{}\"", self.value)
    }
}

/// A dimension value with unit: `30mm`, `100mil`, `1in`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Dimension {
    /// Numeric value.
    pub value: f64,
    /// Unit of measurement.
    pub unit: Unit,
    /// Span covering the dimension.
    pub span: Span,
}

impl Dimension {
    /// Create a new dimension.
    pub fn new(value: f64, unit: Unit, span: Span) -> Self {
        Dimension { value, unit, span }
    }

    /// Convert to nanometers using the core library.
    pub fn to_nm(&self) -> cypcb_core::Nm {
        self.unit.to_nm(self.value)
    }

    /// Convert to a core Dimension (without span).
    pub fn to_core(&self) -> cypcb_core::Dimension {
        cypcb_core::Dimension::new(self.value, self.unit)
    }
}

impl std::fmt::Display for Dimension {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{}", self.value, self.unit)
    }
}

/// Pad shape for footprint definitions.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum PadShape {
    /// Rectangular pad.
    Rect,
    /// Circular pad.
    Circle,
    /// Rounded rectangle pad.
    RoundRect,
    /// Oblong (stadium) pad.
    Oblong,
}

impl PadShape {
    /// Parse a pad shape from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "rect" => Some(PadShape::Rect),
            "circle" => Some(PadShape::Circle),
            "roundrect" => Some(PadShape::RoundRect),
            "oblong" => Some(PadShape::Oblong),
            _ => None,
        }
    }
}

/// A pad definition within a footprint.
///
/// # Example DSL
///
/// ```cypcb
/// pad 1 rect at -2.7mm, -1.905mm size 1.5mm x 0.6mm
/// pad 2 circle at 0mm, 0mm size 1.8mm x 1.8mm drill 1.0mm
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PadDef {
    /// Pad number (e.g., 1, 2, 3).
    pub number: u32,
    /// Pad shape.
    pub shape: PadShape,
    /// X position relative to footprint origin.
    pub x: Dimension,
    /// Y position relative to footprint origin.
    pub y: Dimension,
    /// Pad width.
    pub width: Dimension,
    /// Pad height.
    pub height: Dimension,
    /// Optional drill diameter for through-hole pads.
    pub drill: Option<Dimension>,
    /// Source span.
    pub span: Span,
}

/// A custom footprint definition.
///
/// # Example DSL
///
/// ```cypcb
/// footprint MY_SOIC_8 {
///     description "Custom SOIC-8 with thermal pad"
///     pad 1 rect at -2.7mm, -1.905mm size 1.5mm x 0.6mm
///     pad 2 rect at -2.7mm, -0.635mm size 1.5mm x 0.6mm
///     courtyard 6mm x 5mm
/// }
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FootprintDef {
    /// Footprint name/identifier.
    pub name: Identifier,
    /// Optional description.
    pub description: Option<String>,
    /// Pad definitions.
    pub pads: Vec<PadDef>,
    /// Optional explicit courtyard dimensions (width, height).
    pub courtyard: Option<(Dimension, Dimension)>,
    /// Source span.
    pub span: Span,
}

/// Zone type (keepout vs copper pour).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ZoneKind {
    /// No copper allowed in this region.
    Keepout,
    /// Copper fill zone (pour) - connected to a net.
    CopperPour,
}

impl ZoneKind {
    /// Parse a zone kind from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "keepout" => Some(ZoneKind::Keepout),
            "zone" => Some(ZoneKind::CopperPour),
            _ => None,
        }
    }
}

/// A zone definition (keepout or copper pour).
///
/// Zones define rectangular regions with special properties:
/// - Keepouts prevent copper from being placed in the region
/// - Copper pours fill the region with copper connected to a net
///
/// # Example DSL
///
/// ```cypcb
/// keepout antenna_clearance {
///     bounds 10mm, 10mm to 20mm, 20mm
///     layer all
/// }
///
/// zone gnd_pour {
///     bounds 0mm, 0mm to 50mm, 50mm
///     layer bottom
///     net GND
/// }
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ZoneDef {
    /// Zone type (keepout or copper pour).
    pub kind: ZoneKind,
    /// Optional zone name for reference.
    pub name: Option<Identifier>,
    /// Zone bounds (min_x, min_y, max_x, max_y).
    pub bounds: (Dimension, Dimension, Dimension, Dimension),
    /// Layer this zone applies to (None = all layers).
    pub layer: Option<String>,
    /// Net for copper pour zones (keepouts don't have this).
    pub net: Option<Identifier>,
    /// Source span.
    pub span: Span,
}

/// A manual trace definition.
///
/// Manual traces allow users to define explicit routing between two pins,
/// optionally with via waypoints. These traces can be locked to prevent
/// the autorouter from modifying them.
///
/// # Example DSL
///
/// ```cypcb
/// trace VCC {
///     from R1.1
///     to C1.1
///     via 5mm, 8mm
///     layer Top
///     width 0.4mm
///     locked
/// }
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TraceDef {
    /// Net name this trace belongs to.
    pub net: Identifier,
    /// Starting pin reference.
    pub from: Option<PinRef>,
    /// Ending pin reference.
    pub to: Option<PinRef>,
    /// Via waypoints (positions between from and to).
    pub waypoints: Vec<PositionExpr>,
    /// Copper layer (None = use net default or TopCopper).
    pub layer: Option<String>,
    /// Trace width (None = use net constraint or default).
    pub width: Option<Dimension>,
    /// If true, autorouter should not modify this trace.
    pub locked: bool,
    /// Source span.
    pub span: Span,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_span_merge() {
        let a = Span::new(10, 20);
        let b = Span::new(15, 30);
        let merged = a.merge(b);
        assert_eq!(merged.start, 10);
        assert_eq!(merged.end, 30);
    }

    #[test]
    fn test_span_to_miette() {
        let span = Span::new(5, 15);
        let miette_span: miette::SourceSpan = span.into();
        // miette::SourceSpan is (offset, length)
        assert_eq!(miette_span.offset(), 5);
        assert_eq!(miette_span.len(), 10);
    }

    #[test]
    fn test_component_kind_parse() {
        assert_eq!(ComponentKind::from_str("resistor"), Some(ComponentKind::Resistor));
        assert_eq!(ComponentKind::from_str("ic"), Some(ComponentKind::Ic));
        assert_eq!(ComponentKind::from_str("unknown"), None);
    }

    #[test]
    fn test_layer_type_parse() {
        assert_eq!(LayerType::from_str("copper"), Some(LayerType::Copper));
        assert_eq!(LayerType::from_str("prepreg"), Some(LayerType::Prepreg));
        assert_eq!(LayerType::from_str("unknown"), None);
    }

    #[test]
    fn test_pin_id_display() {
        assert_eq!(format!("{}", PinId::Number(1)), "1");
        assert_eq!(format!("{}", PinId::Name("VCC".into())), "VCC");
    }

    #[test]
    fn test_dimension_to_nm() {
        let dim = Dimension::new(10.0, Unit::Mm, Span::new(0, 4));
        assert_eq!(dim.to_nm().0, 10_000_000);
    }

    #[test]
    fn test_ast_serialize() {
        let source_file = SourceFile {
            version: Some(1),
            definitions: vec![Definition::Board(BoardDef {
                name: Identifier::new("test", Span::new(0, 4)),
                size: Some(SizeProperty {
                    width: Dimension::new(30.0, Unit::Mm, Span::new(0, 4)),
                    height: Dimension::new(20.0, Unit::Mm, Span::new(0, 4)),
                    span: Span::new(0, 20),
                }),
                layers: Some(2),
                stackup: None,
                span: Span::new(0, 50),
            })],
            span: Span::new(0, 100),
        };
        let json = serde_json::to_string(&source_file).expect("serialize");
        assert!(json.contains("\"version\":1"));
        assert!(json.contains("\"type\":\"board\""));
    }

    #[test]
    fn test_zone_kind_parse() {
        assert_eq!(ZoneKind::from_str("keepout"), Some(ZoneKind::Keepout));
        assert_eq!(ZoneKind::from_str("zone"), Some(ZoneKind::CopperPour));
        assert_eq!(ZoneKind::from_str("unknown"), None);
    }

    #[test]
    fn test_pad_shape_parse() {
        assert_eq!(PadShape::from_str("rect"), Some(PadShape::Rect));
        assert_eq!(PadShape::from_str("circle"), Some(PadShape::Circle));
        assert_eq!(PadShape::from_str("roundrect"), Some(PadShape::RoundRect));
        assert_eq!(PadShape::from_str("oblong"), Some(PadShape::Oblong));
        assert_eq!(PadShape::from_str("unknown"), None);
    }

    #[test]
    fn test_current_unit_parse() {
        assert_eq!(CurrentUnit::from_str("mA"), Some(CurrentUnit::Milliamps));
        assert_eq!(CurrentUnit::from_str("A"), Some(CurrentUnit::Amps));
        assert_eq!(CurrentUnit::from_str("unknown"), None);
    }

    #[test]
    fn test_current_value_conversions() {
        let ma_val = CurrentValue::new(500.0, CurrentUnit::Milliamps, Span::new(0, 5));
        assert!((ma_val.to_milliamps() - 500.0).abs() < 0.001);
        assert!((ma_val.to_amps() - 0.5).abs() < 0.001);

        let a_val = CurrentValue::new(2.0, CurrentUnit::Amps, Span::new(0, 2));
        assert!((a_val.to_milliamps() - 2000.0).abs() < 0.001);
        assert!((a_val.to_amps() - 2.0).abs() < 0.001);
    }

    #[test]
    fn test_current_value_display() {
        let ma = CurrentValue::new(500.0, CurrentUnit::Milliamps, Span::new(0, 5));
        assert_eq!(format!("{}", ma), "500mA");

        let a = CurrentValue::new(2.5, CurrentUnit::Amps, Span::new(0, 4));
        assert_eq!(format!("{}", a), "2.5A");
    }
}

//! Tree-sitter to AST conversion.
//!
//! This module provides the [`CypcbParser`] which uses Tree-sitter to parse
//! source code and convert the resulting CST (Concrete Syntax Tree) into
//! typed AST nodes.
//!
//! # Example
//!
//! ```rust
//! use cypcb_parser::{CypcbParser, parse};
//!
//! let source = r#"
//! version 1
//! board test {
//!     size 30mm x 20mm
//!     layers 2
//! }
//! "#;
//!
//! let mut parser = CypcbParser::new();
//! let result = parser.parse(source);
//!
//! if result.is_ok() {
//!     let ast = result.value;
//!     println!("Parsed {} definitions", ast.definitions.len());
//! } else {
//!     for error in &result.errors {
//!         eprintln!("{:?}", error);
//!     }
//! }
//! ```

use crate::ast::{
    BoardDef, ComponentDef, ComponentKind, CurrentUnit, CurrentValue, Definition, Dimension,
    FootprintDef, Identifier, LayerType, NetAssignment, NetConstraints, NetDef, PadDef, PadShape,
    PinId, PinRef, PositionExpr, RotationExpr, SizeProperty, SourceFile, Span, StackupDef,
    StackupLayer, StringLit, TraceDef, ZoneDef, ZoneKind,
};
use crate::errors::{ParseError, ParseResult};
use crate::node_kinds;
use cypcb_core::Unit;
use tree_sitter::{Node, Parser, Tree};

/// Parser for CodeYourPCB source files.
///
/// Uses Tree-sitter for parsing and converts the resulting CST to typed AST nodes.
/// The parser supports error recovery, collecting errors while continuing to parse.
pub struct CypcbParser {
    parser: Parser,
}

impl CypcbParser {
    /// Create a new parser instance.
    ///
    /// # Panics
    ///
    /// Panics if the Tree-sitter language cannot be loaded.
    pub fn new() -> Self {
        let mut parser = Parser::new();
        parser
            .set_language(&crate::language())
            .expect("Failed to set cypcb language");
        CypcbParser { parser }
    }

    /// Parse source code and return the AST with any errors.
    ///
    /// The parser uses error recovery, so it will return a partial AST
    /// even if there are syntax errors.
    pub fn parse(&mut self, source: &str) -> ParseResult<SourceFile> {
        let tree = match self.parser.parse(source, None) {
            Some(t) => t,
            None => {
                return ParseResult::new(
                    SourceFile {
                        version: None,
                        definitions: Vec::new(),
                        span: Span::new(0, source.len()),
                    },
                    vec![ParseError::syntax(
                        "Failed to parse source",
                        source.to_string(),
                        (0, source.len().min(1)),
                    )],
                );
            }
        };

        let mut errors = Vec::new();
        let ast = self.convert_source_file(source, &tree, &mut errors);
        ParseResult::new(ast, errors)
    }

    /// Convert the root node to a SourceFile AST node.
    fn convert_source_file(
        &self,
        source: &str,
        tree: &Tree,
        errors: &mut Vec<ParseError>,
    ) -> SourceFile {
        let root = tree.root_node();
        let span = span_of(&root);

        // Collect errors from ERROR nodes
        self.collect_errors(source, &root, errors);

        let mut version = None;
        let mut definitions = Vec::new();

        let mut cursor = root.walk();
        for child in root.children(&mut cursor) {
            match child.kind() {
                node_kinds::VERSION_STATEMENT => {
                    version = self.convert_version(source, &child, errors);
                }
                node_kinds::BOARD_DEFINITION => {
                    if let Some(board) = self.convert_board(source, &child, errors) {
                        definitions.push(Definition::Board(board));
                    }
                }
                node_kinds::COMPONENT_DEFINITION => {
                    if let Some(component) = self.convert_component(source, &child, errors) {
                        definitions.push(Definition::Component(component));
                    }
                }
                node_kinds::NET_DEFINITION => {
                    if let Some(net) = self.convert_net(source, &child, errors) {
                        definitions.push(Definition::Net(net));
                    }
                }
                "footprint_definition" => {
                    if let Some(fp) = self.convert_footprint_definition(source, &child, errors) {
                        definitions.push(Definition::Footprint(fp));
                    }
                }
                "zone_definition" => {
                    if let Some(zone) = self.convert_zone(source, &child, errors) {
                        definitions.push(Definition::Zone(zone));
                    }
                }
                "trace_definition" => {
                    if let Some(trace) = self.convert_trace_definition(source, &child, errors) {
                        definitions.push(Definition::Trace(trace));
                    }
                }
                _ => {}
            }
        }

        SourceFile {
            version,
            definitions,
            span,
        }
    }

    /// Recursively collect ERROR nodes and report them.
    fn collect_errors(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) {
        if node.is_error() {
            let span = span_of(node);
            let text = node_text(source, node);
            errors.push(ParseError::syntax(
                format!("unexpected token: '{}'", text.chars().take(20).collect::<String>()),
                source.to_string(),
                span.to_miette(),
            ));
        }

        // Check children recursively
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            self.collect_errors(source, &child, errors);
        }
    }

    /// Convert a version statement node.
    fn convert_version(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<u32> {
        let number_node = get_child_by_field(node, "number")?;
        let text = node_text(source, &number_node);
        match text.parse::<u32>() {
            Ok(v) => {
                if v == 0 {
                    errors.push(ParseError::invalid_version(
                        "version must be at least 1",
                        source.to_string(),
                        span_of(&number_node).to_miette(),
                    ));
                }
                Some(v)
            }
            Err(_) => {
                errors.push(ParseError::invalid_number(
                    text,
                    source.to_string(),
                    span_of(&number_node).to_miette(),
                ));
                None
            }
        }
    }

    /// Convert a board definition node.
    fn convert_board(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<BoardDef> {
        let name_node = get_child_by_field(node, "name")?;
        let name = Identifier::new(node_text(source, &name_node), span_of(&name_node));

        let mut size = None;
        let mut layers = None;
        let mut stackup = None;

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            // board_property is a choice node, so we need to check both the wrapper
            // and the actual property types
            let property_node = if child.kind() == "board_property" {
                // Get the first named child which is the actual property
                child.named_child(0)
            } else {
                Some(child)
            };

            if let Some(prop) = property_node {
                match prop.kind() {
                    node_kinds::SIZE_PROPERTY => {
                        size = self.convert_size(source, &prop, errors);
                    }
                    node_kinds::LAYERS_PROPERTY => {
                        layers = self.convert_layers(source, &prop, errors);
                    }
                    "stackup_property" => {
                        stackup = self.convert_stackup(source, &prop, errors);
                    }
                    _ => {}
                }
            }
        }

        Some(BoardDef {
            name,
            size,
            layers,
            stackup,
            span: span_of(node),
        })
    }

    /// Convert a size property node.
    fn convert_size(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<SizeProperty> {
        let width_node = get_child_by_field(node, "width")?;
        let height_node = get_child_by_field(node, "height")?;

        let width = self.convert_dimension(source, &width_node, errors)?;
        let height = self.convert_dimension(source, &height_node, errors)?;

        Some(SizeProperty {
            width,
            height,
            span: span_of(node),
        })
    }

    /// Convert a layers property node.
    fn convert_layers(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<u8> {
        let count_node = get_child_by_field(node, "count")?;
        let text = node_text(source, &count_node);
        match text.parse::<u32>() {
            Ok(count) => {
                // Validate layer count (must be even, 2-32)
                if count < 2 || count > 32 || count % 2 != 0 {
                    errors.push(ParseError::invalid_layers(
                        count,
                        source.to_string(),
                        span_of(&count_node).to_miette(),
                    ));
                }
                Some(count as u8)
            }
            Err(_) => {
                errors.push(ParseError::invalid_number(
                    text,
                    source.to_string(),
                    span_of(&count_node).to_miette(),
                ));
                None
            }
        }
    }

    /// Convert a stackup property node.
    fn convert_stackup(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<StackupDef> {
        let mut layers = Vec::new();

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            if child.kind() == "stackup_layer" {
                if let Some(layer) = self.convert_stackup_layer(source, &child, errors) {
                    layers.push(layer);
                }
            }
        }

        Some(StackupDef {
            layers,
            span: span_of(node),
        })
    }

    /// Convert a stackup layer node.
    fn convert_stackup_layer(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<StackupLayer> {
        let type_node = get_child_by_field(node, "layer_type")?;
        let type_text = node_text(source, &type_node);

        let layer_type = match LayerType::from_str(type_text) {
            Some(t) => t,
            None => {
                errors.push(ParseError::unknown_layer_type(
                    type_text,
                    source.to_string(),
                    span_of(&type_node).to_miette(),
                ));
                return None;
            }
        };

        let thickness = get_child_by_field(node, "thickness")
            .and_then(|n| self.convert_dimension(source, &n, errors));

        Some(StackupLayer {
            layer_type,
            thickness,
            span: span_of(node),
        })
    }

    /// Convert a component definition node.
    fn convert_component(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<ComponentDef> {
        let refdes_node = get_child_by_field(node, "refdes")?;
        let type_node = get_child_by_field(node, "type")?;
        let footprint_node = get_child_by_field(node, "footprint")?;

        let refdes = Identifier::new(node_text(source, &refdes_node), span_of(&refdes_node));
        let type_text = node_text(source, &type_node);

        let kind = match ComponentKind::from_str(type_text) {
            Some(k) => k,
            None => {
                errors.push(ParseError::unknown_component(
                    type_text,
                    source.to_string(),
                    span_of(&type_node).to_miette(),
                ));
                ComponentKind::Generic
            }
        };

        let footprint = self.convert_string_literal(source, &footprint_node);

        let mut value = None;
        let mut position = None;
        let mut rotation = None;
        let mut net_assignments = Vec::new();

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            match child.kind() {
                node_kinds::VALUE_PROPERTY => {
                    if let Some(val_node) = get_child_by_field(&child, "value") {
                        value = Some(self.convert_string_literal(source, &val_node));
                    }
                }
                node_kinds::POSITION_PROPERTY => {
                    position = self.convert_position(source, &child, errors);
                }
                node_kinds::ROTATION_PROPERTY => {
                    rotation = self.convert_rotation(source, &child, errors);
                }
                "net_assignment" => {
                    if let Some(assignment) = self.convert_net_assignment(source, &child, errors) {
                        net_assignments.push(assignment);
                    }
                }
                _ => {}
            }
        }

        Some(ComponentDef {
            refdes,
            kind,
            footprint,
            value,
            position,
            rotation,
            net_assignments,
            span: span_of(node),
        })
    }

    /// Convert a position property node.
    fn convert_position(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<PositionExpr> {
        let x_node = get_child_by_field(node, "x")?;
        let y_node = get_child_by_field(node, "y")?;

        let x = self.convert_dimension(source, &x_node, errors)?;
        let y = self.convert_dimension(source, &y_node, errors)?;

        Some(PositionExpr {
            x,
            y,
            span: span_of(node),
        })
    }

    /// Convert a rotation property node.
    fn convert_rotation(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<RotationExpr> {
        let angle_node = get_child_by_field(node, "angle")?;
        let text = node_text(source, &angle_node);

        let angle = match text.parse::<f64>() {
            Ok(a) => a,
            Err(_) => {
                errors.push(ParseError::invalid_number(
                    text,
                    source.to_string(),
                    span_of(&angle_node).to_miette(),
                ));
                return None;
            }
        };

        Some(RotationExpr {
            angle,
            span: span_of(node),
        })
    }

    /// Convert a net assignment node.
    fn convert_net_assignment(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<NetAssignment> {
        let pin_node = get_child_by_field(node, "pin")?;
        let net_node = get_child_by_field(node, "net")?;

        let pin = self.convert_pin_identifier(source, &pin_node);
        let net = Identifier::new(node_text(source, &net_node), span_of(&net_node));

        Some(NetAssignment {
            pin,
            net,
            span: span_of(node),
        })
    }

    /// Convert a net definition node.
    fn convert_net(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<NetDef> {
        let name_node = get_child_by_field(node, "name")?;
        let name = Identifier::new(node_text(source, &name_node), span_of(&name_node));

        let mut constraints = None;
        let mut connections = Vec::new();

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            match child.kind() {
                "net_constraint_block" => {
                    constraints = self.convert_net_constraints(source, &child, errors);
                }
                "pin_ref_list" => {
                    connections = self.convert_pin_ref_list(source, &child, errors);
                }
                node_kinds::PIN_REF => {
                    if let Some(pin_ref) = self.convert_pin_ref(source, &child, errors) {
                        connections.push(pin_ref);
                    }
                }
                _ => {}
            }
        }

        Some(NetDef {
            name,
            constraints,
            connections,
            span: span_of(node),
        })
    }

    /// Convert a net constraints block.
    fn convert_net_constraints(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<NetConstraints> {
        let mut width = None;
        let mut clearance = None;
        let mut current = None;

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            // net_constraint is a choice node wrapping width_constraint, clearance_constraint, or current_constraint
            let constraint_node = if child.kind() == "net_constraint" {
                child.named_child(0)
            } else {
                Some(child)
            };

            if let Some(constraint) = constraint_node {
                match constraint.kind() {
                    "width_constraint" => {
                        if let Some(val_node) = get_child_by_field(&constraint, "value") {
                            width = self.convert_dimension(source, &val_node, errors);
                        }
                    }
                    "clearance_constraint" => {
                        if let Some(val_node) = get_child_by_field(&constraint, "value") {
                            clearance = self.convert_dimension(source, &val_node, errors);
                        }
                    }
                    "current_constraint" => {
                        if let Some(val_node) = get_child_by_field(&constraint, "value") {
                            current = self.convert_current_value(source, &val_node, errors);
                        }
                    }
                    _ => {}
                }
            }
        }

        Some(NetConstraints {
            width,
            clearance,
            current,
            span: span_of(node),
        })
    }

    /// Convert a current value node (e.g., "500mA" or "2A").
    fn convert_current_value(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<CurrentValue> {
        let amount_node = get_child_by_field(node, "amount")?;
        let text = node_text(source, &amount_node);

        let value = match text.parse::<f64>() {
            Ok(v) => v,
            Err(_) => {
                errors.push(ParseError::invalid_number(
                    text,
                    source.to_string(),
                    span_of(&amount_node).to_miette(),
                ));
                return None;
            }
        };

        let unit_node = get_child_by_field(node, "unit")?;
        let unit_text = node_text(source, &unit_node);

        let unit = match CurrentUnit::from_str(unit_text) {
            Some(u) => u,
            None => {
                errors.push(ParseError::unknown_unit(
                    unit_text,
                    source.to_string(),
                    span_of(&unit_node).to_miette(),
                ));
                return None;
            }
        };

        Some(CurrentValue::new(value, unit, span_of(node)))
    }

    /// Convert a pin reference list.
    fn convert_pin_ref_list(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Vec<PinRef> {
        let mut refs = Vec::new();

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            if child.kind() == node_kinds::PIN_REF {
                if let Some(pin_ref) = self.convert_pin_ref(source, &child, errors) {
                    refs.push(pin_ref);
                }
            }
        }

        refs
    }

    /// Convert a pin reference node.
    fn convert_pin_ref(&self, source: &str, node: &Node, _errors: &mut Vec<ParseError>) -> Option<PinRef> {
        let component_node = get_child_by_field(node, "component")?;
        let pin_node = get_child_by_field(node, "pin")?;

        let component = Identifier::new(node_text(source, &component_node), span_of(&component_node));
        let pin = self.convert_pin_identifier(source, &pin_node);

        Some(PinRef {
            component,
            pin,
            span: span_of(node),
        })
    }

    /// Convert a pin identifier (number or name).
    fn convert_pin_identifier(&self, source: &str, node: &Node) -> PinId {
        let text = node_text(source, node);
        // Try to parse as number first
        if let Ok(n) = text.parse::<u32>() {
            PinId::Number(n)
        } else {
            PinId::Name(text.to_string())
        }
    }

    /// Convert a dimension node.
    fn convert_dimension(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<Dimension> {
        // Check for negative sign
        let is_negative = get_child_by_field(node, "sign").is_some();

        let value_node = get_child_by_field(node, "value")?;
        let text = node_text(source, &value_node);

        let value = match text.parse::<f64>() {
            Ok(v) => {
                if is_negative {
                    -v
                } else {
                    v
                }
            }
            Err(_) => {
                errors.push(ParseError::invalid_number(
                    text,
                    source.to_string(),
                    span_of(&value_node).to_miette(),
                ));
                return None;
            }
        };

        let unit = if let Some(unit_node) = get_child_by_field(node, "unit") {
            let unit_text = node_text(source, &unit_node);
            match unit_text.parse::<Unit>() {
                Ok(u) => u,
                Err(_) => {
                    errors.push(ParseError::unknown_unit(
                        unit_text,
                        source.to_string(),
                        span_of(&unit_node).to_miette(),
                    ));
                    Unit::Mm // Default to mm
                }
            }
        } else {
            Unit::Mm // Default unit
        };

        Some(Dimension::new(value, unit, span_of(node)))
    }

    /// Convert a string literal node (extracts value without quotes).
    fn convert_string_literal(&self, source: &str, node: &Node) -> StringLit {
        let full_text = node_text(source, node);
        // Strip quotes
        let value = full_text.trim_matches('"').to_string();
        StringLit::new(value, span_of(node))
    }

    /// Convert a footprint definition node.
    fn convert_footprint_definition(
        &self,
        source: &str,
        node: &Node,
        errors: &mut Vec<ParseError>,
    ) -> Option<FootprintDef> {
        let name_node = get_child_by_field(node, "name")?;
        let name = Identifier::new(node_text(source, &name_node), span_of(&name_node));

        let mut description: Option<String> = None;
        let mut pads: Vec<PadDef> = Vec::new();
        let mut courtyard: Option<(Dimension, Dimension)> = None;

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            // footprint_property is a choice node
            let property_node = if child.kind() == "footprint_property" {
                child.named_child(0)
            } else {
                Some(child)
            };

            if let Some(prop) = property_node {
                match prop.kind() {
                    "description_property" => {
                        if let Some(text_node) = get_child_by_field(&prop, "text") {
                            let lit = self.convert_string_literal(source, &text_node);
                            description = Some(lit.value);
                        }
                    }
                    "pad_definition" => {
                        if let Some(pad) = self.convert_pad_definition(source, &prop, errors) {
                            pads.push(pad);
                        }
                    }
                    "courtyard_property" => {
                        let width = get_child_by_field(&prop, "width")
                            .and_then(|n| self.convert_dimension(source, &n, errors));
                        let height = get_child_by_field(&prop, "height")
                            .and_then(|n| self.convert_dimension(source, &n, errors));

                        if let (Some(w), Some(h)) = (width, height) {
                            courtyard = Some((w, h));
                        }
                    }
                    _ => {}
                }
            }
        }

        Some(FootprintDef {
            name,
            description,
            pads,
            courtyard,
            span: span_of(node),
        })
    }

    /// Convert a pad definition node.
    fn convert_pad_definition(
        &self,
        source: &str,
        node: &Node,
        errors: &mut Vec<ParseError>,
    ) -> Option<PadDef> {
        let number_node = get_child_by_field(node, "number")?;
        let number_text = node_text(source, &number_node);
        let number = match number_text.parse::<u32>() {
            Ok(n) => n,
            Err(_) => {
                errors.push(ParseError::invalid_number(
                    number_text,
                    source.to_string(),
                    span_of(&number_node).to_miette(),
                ));
                return None;
            }
        };

        let shape_node = get_child_by_field(node, "shape")?;
        let shape_text = node_text(source, &shape_node);
        let shape = match PadShape::from_str(shape_text) {
            Some(s) => s,
            None => {
                errors.push(ParseError::syntax(
                    format!("unknown pad shape: '{}'", shape_text),
                    source.to_string(),
                    span_of(&shape_node).to_miette(),
                ));
                return None;
            }
        };

        let x = get_child_by_field(node, "x")
            .and_then(|n| self.convert_dimension(source, &n, errors))?;
        let y = get_child_by_field(node, "y")
            .and_then(|n| self.convert_dimension(source, &n, errors))?;
        let width = get_child_by_field(node, "width")
            .and_then(|n| self.convert_dimension(source, &n, errors))?;
        let height = get_child_by_field(node, "height")
            .and_then(|n| self.convert_dimension(source, &n, errors))?;

        // Optional drill spec
        let drill = get_child_by_field(node, "drill").and_then(|drill_spec| {
            // drill_spec has a dimension child
            let mut drill_cursor = drill_spec.walk();
            for drill_child in drill_spec.children(&mut drill_cursor) {
                if drill_child.kind() == "dimension" {
                    return self.convert_dimension(source, &drill_child, errors);
                }
            }
            None
        });

        Some(PadDef {
            number,
            shape,
            x,
            y,
            width,
            height,
            drill,
            span: span_of(node),
        })
    }

    /// Convert a zone definition node.
    fn convert_zone(&self, source: &str, node: &Node, errors: &mut Vec<ParseError>) -> Option<ZoneDef> {
        let kind_node = get_child_by_field(node, "kind")?;
        let kind_text = node_text(source, &kind_node);
        let kind = ZoneKind::from_str(kind_text)?;

        let name = get_child_by_field(node, "name")
            .map(|n| Identifier::new(node_text(source, &n), span_of(&n)));

        let mut bounds: Option<(Dimension, Dimension, Dimension, Dimension)> = None;
        let mut layer: Option<String> = None;
        let mut net: Option<Identifier> = None;

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            let property_node = if child.kind() == "zone_property" {
                child.named_child(0)
            } else {
                Some(child)
            };

            if let Some(prop) = property_node {
                match prop.kind() {
                    "zone_bounds" => {
                        let min_x = get_child_by_field(&prop, "min_x")
                            .and_then(|n| self.convert_dimension(source, &n, errors));
                        let min_y = get_child_by_field(&prop, "min_y")
                            .and_then(|n| self.convert_dimension(source, &n, errors));
                        let max_x = get_child_by_field(&prop, "max_x")
                            .and_then(|n| self.convert_dimension(source, &n, errors));
                        let max_y = get_child_by_field(&prop, "max_y")
                            .and_then(|n| self.convert_dimension(source, &n, errors));

                        if let (Some(x1), Some(y1), Some(x2), Some(y2)) = (min_x, min_y, max_x, max_y) {
                            bounds = Some((x1, y1, x2, y2));
                        }
                    }
                    "zone_layer" => {
                        if let Some(layer_node) = get_child_by_field(&prop, "name") {
                            layer = Some(node_text(source, &layer_node).to_string());
                        }
                    }
                    "zone_net" => {
                        if let Some(net_node) = get_child_by_field(&prop, "net") {
                            net = Some(Identifier::new(
                                node_text(source, &net_node),
                                span_of(&net_node),
                            ));
                        }
                    }
                    _ => {}
                }
            }
        }

        // Bounds are required
        let bounds = bounds?;

        Some(ZoneDef {
            kind,
            name,
            bounds,
            layer,
            net,
            span: span_of(node),
        })
    }

    /// Convert a trace definition node.
    fn convert_trace_definition(
        &self,
        source: &str,
        node: &Node,
        errors: &mut Vec<ParseError>,
    ) -> Option<TraceDef> {
        let net_node = get_child_by_field(node, "net")?;
        let net = Identifier::new(node_text(source, &net_node), span_of(&net_node));

        let mut from: Option<PinRef> = None;
        let mut to: Option<PinRef> = None;
        let mut waypoints: Vec<PositionExpr> = Vec::new();
        let mut layer: Option<String> = None;
        let mut width: Option<Dimension> = None;
        let mut locked = false;

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            match child.kind() {
                "trace_from" => {
                    if let Some(pin_node) = get_child_by_field(&child, "pin") {
                        from = self.convert_pin_ref(source, &pin_node, errors);
                    }
                }
                "trace_to" => {
                    if let Some(pin_node) = get_child_by_field(&child, "pin") {
                        to = self.convert_pin_ref(source, &pin_node, errors);
                    }
                }
                "trace_via" => {
                    let x = get_child_by_field(&child, "x")
                        .and_then(|n| self.convert_dimension(source, &n, errors));
                    let y = get_child_by_field(&child, "y")
                        .and_then(|n| self.convert_dimension(source, &n, errors));

                    if let (Some(x), Some(y)) = (x, y) {
                        waypoints.push(PositionExpr {
                            x,
                            y,
                            span: span_of(&child),
                        });
                    }
                }
                "trace_layer" => {
                    if let Some(name_node) = get_child_by_field(&child, "name") {
                        layer = Some(node_text(source, &name_node).to_string());
                    }
                }
                "trace_width" => {
                    if let Some(val_node) = get_child_by_field(&child, "value") {
                        width = self.convert_dimension(source, &val_node, errors);
                    }
                }
                "trace_locked" => {
                    locked = true;
                }
                _ => {}
            }
        }

        Some(TraceDef {
            net,
            from,
            to,
            waypoints,
            layer,
            width,
            locked,
            span: span_of(node),
        })
    }
}

impl Default for CypcbParser {
    fn default() -> Self {
        Self::new()
    }
}

/// Helper: get the text of a node from the source.
fn node_text<'a>(source: &'a str, node: &Node) -> &'a str {
    &source[node.start_byte()..node.end_byte()]
}

/// Helper: get a child node by field name.
fn get_child_by_field<'a>(node: &'a Node, name: &str) -> Option<Node<'a>> {
    node.child_by_field_name(name)
}

/// Helper: convert a tree-sitter node to our Span type.
fn span_of(node: &Node) -> Span {
    Span::new(node.start_byte(), node.end_byte())
}

/// Convenience function to parse source code.
///
/// # Example
///
/// ```rust
/// use cypcb_parser::parse;
///
/// let result = parse("version 1\nboard test { size 10mm x 10mm }");
/// assert!(result.is_ok());
/// ```
pub fn parse(source: &str) -> ParseResult<SourceFile> {
    let mut parser = CypcbParser::new();
    parser.parse(source)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_board() {
        let source = r#"
version 1

board test {
    size 100mm x 50mm
    layers 2
}
"#;
        let mut parser = CypcbParser::new();
        let result = parser.parse(source);
        assert!(result.is_ok(), "errors: {:?}", result.errors);

        let ast = result.value;
        assert_eq!(ast.version, Some(1));
        assert_eq!(ast.definitions.len(), 1);

        if let Definition::Board(board) = &ast.definitions[0] {
            assert_eq!(board.name.value, "test");
            let size = board.size.as_ref().expect("size should be present");
            assert!((size.width.value - 100.0).abs() < 0.001);
            assert_eq!(size.width.unit, Unit::Mm);
            assert!((size.height.value - 50.0).abs() < 0.001);
            assert_eq!(board.layers, Some(2));
        } else {
            panic!("expected board definition");
        }
    }

    #[test]
    fn test_parse_component() {
        let source = r#"
component R1 resistor "0402" {
    value "10k"
    at 10mm, 8mm
    rotate 90
}
"#;
        let result = parse(source);
        assert!(result.is_ok(), "errors: {:?}", result.errors);

        let ast = result.value;
        assert_eq!(ast.definitions.len(), 1);

        if let Definition::Component(comp) = &ast.definitions[0] {
            assert_eq!(comp.refdes.value, "R1");
            assert_eq!(comp.kind, ComponentKind::Resistor);
            assert_eq!(comp.footprint.value, "0402");
            assert_eq!(comp.value.as_ref().map(|v| &v.value), Some(&"10k".to_string()));

            let pos = comp.position.as_ref().expect("position should be present");
            assert!((pos.x.value - 10.0).abs() < 0.001);
            assert!((pos.y.value - 8.0).abs() < 0.001);

            let rot = comp.rotation.as_ref().expect("rotation should be present");
            assert!((rot.angle - 90.0).abs() < 0.001);
        } else {
            panic!("expected component definition");
        }
    }

    #[test]
    fn test_parse_net() {
        let source = r#"
net VCC {
    J1.1
    R1.1
    U1.VCC
}
"#;
        let result = parse(source);
        assert!(result.is_ok(), "errors: {:?}", result.errors);

        let ast = result.value;
        assert_eq!(ast.definitions.len(), 1);

        if let Definition::Net(net) = &ast.definitions[0] {
            assert_eq!(net.name.value, "VCC");
            assert_eq!(net.connections.len(), 3);

            assert_eq!(net.connections[0].component.value, "J1");
            assert!(matches!(net.connections[0].pin, PinId::Number(1)));

            assert_eq!(net.connections[1].component.value, "R1");
            assert!(matches!(net.connections[1].pin, PinId::Number(1)));

            assert_eq!(net.connections[2].component.value, "U1");
            if let PinId::Name(name) = &net.connections[2].pin {
                assert_eq!(name, "VCC");
            } else {
                panic!("expected named pin");
            }
        } else {
            panic!("expected net definition");
        }
    }

    #[test]
    fn test_parse_net_with_constraints() {
        // Grammar uses space-separated constraints, not comma-separated
        let source = r#"
net POWER [width 0.5mm clearance 0.3mm] {
    J1.1
    U1.VIN
}
"#;
        let result = parse(source);
        assert!(result.is_ok(), "errors: {:?}", result.errors);

        let ast = result.value;
        if let Definition::Net(net) = &ast.definitions[0] {
            assert_eq!(net.name.value, "POWER");
            let constraints = net.constraints.as_ref().expect("constraints should be present");
            let width = constraints.width.as_ref().expect("width should be present");
            assert!((width.value - 0.5).abs() < 0.001);
            let clearance = constraints.clearance.as_ref().expect("clearance should be present");
            assert!((clearance.value - 0.3).abs() < 0.001);
        } else {
            panic!("expected net definition");
        }
    }

    #[test]
    fn test_error_recovery() {
        // Invalid syntax: wrong token in component definition
        let source = r#"
board test {
    size 10mm x 10mm
}
component R1 resistor { }
"#;
        let result = parse(source);

        // The component is missing the required footprint string
        // Tree-sitter will mark this as an error
        assert!(result.has_errors(), "expected errors: got AST: {:?}", result.value);
    }

    #[test]
    fn test_span_accuracy() {
        let source = "version 1";
        let result = parse(source);

        assert!(result.is_ok());
        let ast = result.value;

        // The entire source should be covered
        assert_eq!(ast.span.start, 0);
        assert_eq!(ast.span.end, source.len());
    }

    #[test]
    fn test_syntax_error_unknown_type() {
        // Note: The grammar has a fixed set of component types (resistor, capacitor, etc.)
        // An unknown type like "badtype" will cause a Tree-sitter syntax error,
        // not an UnknownComponent error from our converter.
        let source = r#"
component X1 badtype "0402" {
    at 0mm, 0mm
}
"#;
        let result = parse(source);

        // Should have a syntax error because "badtype" isn't a valid component_type
        assert!(result.has_errors(), "expected syntax error for unknown type");
    }

    #[test]
    fn test_complete_example() {
        let source = r#"
// LED blink circuit
version 1

board blink {
    size 30mm x 20mm
    layers 2
}

component R1 resistor "0402" {
    value "330"
    at 10mm, 8mm
}

component LED1 led "0603" {
    at 15mm, 8mm
}

component J1 connector "pin_header_1x2" {
    at 5mm, 8mm
}

net VCC {
    J1.1
    R1.1
}

net GND {
    J1.2
    LED1.cathode
}

net LED_SIGNAL {
    R1.2
    LED1.anode
}
"#;
        let result = parse(source);
        assert!(result.is_ok(), "errors: {:?}", result.errors);

        let ast = result.value;
        assert_eq!(ast.version, Some(1));
        // 1 board + 3 components + 3 nets = 7 definitions
        assert_eq!(ast.definitions.len(), 7);

        // Verify JSON serialization
        let json = serde_json::to_string_pretty(&ast).expect("should serialize");
        println!("JSON output:\n{}", json);
        assert!(json.contains("\"version\": 1") || json.contains("\"version\":1"), "expected version:1 in {}", json);
        assert!(json.contains("blink"), "expected blink in {}", json);
    }

    #[test]
    fn test_multiple_errors() {
        let source = r#"
board test { size 10mm x 10mm layers -1 }
component X1 badtype "fp" { at 0mm, 0mm }
"#;
        let result = parse(source);

        // Should have multiple errors
        assert!(result.has_errors());
        // Parsing should still produce partial results
        assert!(!result.value.definitions.is_empty());
    }

    #[test]
    fn test_default_units() {
        let source = r#"
board test {
    size 100 x 50
}
"#;
        let result = parse(source);
        // Unitless dimensions default to mm
        if let Definition::Board(board) = &result.value.definitions[0] {
            let size = board.size.as_ref().expect("size should be present");
            assert_eq!(size.width.unit, Unit::Mm);
