        assert_eq!(result.value.version, None);
        assert_eq!(result.value.definitions.len(), 1);
    }

    #[test]
    fn test_decimal_dimensions() {
        let source = r#"
board test {
    size 25.4mm x 12.7mm
}
component R1 resistor "0402" {
    at 1.5mm, 0.75mm
    rotate 45.5
}
"#;
