content.text:
//! CodeYourPCB Parser
//!
//! Tree-sitter based parser for the CodeYourPCB DSL.
//! Provides incremental parsing with error recovery.
//!
//! # Overview
//!
//! This crate provides:
//! - Tree-sitter grammar bindings for the CodeYourPCB DSL (requires `tree-sitter-parser` feature)
//! - AST (Abstract Syntax Tree) type definitions
//! - Tree-sitter CST to typed AST conversion (requires `tree-sitter-parser` feature)
//! - Rich error reporting with miette integration
//!
//! # Feature Flags
//!
//! - `tree-sitter-parser` (default): Enables tree-sitter parsing with C code compilation.
//!   Disable this feature for WASM builds where C compilation is not available.
//!
//! # Grammar
//!
//! The grammar supports the following constructs:
//!
//! ```cypcb
//! version 1
//!
//! board blink {
//!     size 30mm x 20mm
//!     layers 2
//! }
//!
//! component R1 resistor "0402" {
//!     value "330"
//!     at 10mm, 8mm
//! }
//!
//! net VCC {
//!     J1.1
//!     R1.1
//! }
//! ```
//!
//! # Quick Start
//!
//! ```rust
//! use cypcb_parser::{parse, CypcbParser};
//!
//! // Convenience function
//! let result = parse("version 1\nboard test { size 10mm x 10mm }");
//! if result.is_ok() {
//!     println!("Parsed {} definitions", result.value.definitions.len());
//! }
//!
//! // Or use the parser struct for multiple parses
//! let mut parser = CypcbParser::new();
//! let result = parser.parse("board another { size 20mm x 20mm }");
//! ```
//!
//! # Low-level Usage
//!
//! For direct access to the Tree-sitter parse tree:
//!
//! ```rust
//! use cypcb_parser::language;
//! use tree_sitter::Parser;
//!
//! let mut parser = Parser::new();
//! parser.set_language(&language()).unwrap();
//!
//! let source = "version 1\nboard test { size 10mm x 10mm }";
//! let tree = parser.parse(source, None).unwrap();
//! println!("{}", tree.root_node().to_sexp());
//! ```

pub mod ast;
pub mod errors;

// Tree-sitter parser module only available with the feature
#[cfg(feature = "tree-sitter-parser")]
pub mod parser;

#[cfg(feature = "tree-sitter-parser")]
use tree_sitter::Language;

// Re-export AST types (always available)
pub use ast::{
    BoardDef, ComponentDef, ComponentKind, Definition, Dimension, Identifier, NetDef, PinId,
    PinRef, PositionExpr, SizeProperty, SourceFile, Span, StringLit,
};

// Re-export error types (always available)
pub use errors::{ParseError, ParseResult};

// Re-export parser types (only with feature)
#[cfg(feature = "tree-sitter-parser")]
pub use parser::{parse, CypcbParser};

// Link to the compiled Tree-sitter grammar (only with feature)
#[cfg(feature = "tree-sitter-parser")]
extern "C" {
    fn tree_sitter_cypcb() -> Language;
}

/// Returns the Tree-sitter language for CodeYourPCB DSL.
///
/// This language can be used with a `tree_sitter::Parser` for parsing
/// `.cypcb` source files.
///
/// # Safety
///
/// This function is safe because it only calls the generated Tree-sitter
/// language function, which returns a static language definition.
///
/// # Availability
///
/// This function is only available with the `tree-sitter-parser` feature.
#[cfg(feature = "tree-sitter-parser")]
pub fn language() -> Language {
    unsafe { tree_sitter_cypcb() }
}

/// Node kind constants for the grammar.
///
/// These match the node types generated by Tree-sitter and can be used
/// for efficient node type checking without string comparisons.
#[cfg(feature = "tree-sitter-parser")]
pub mod node_kinds {
    pub const SOURCE_FILE: &str = "source_file";
    pub const VERSION_STATEMENT: &str = "version_statement";
    pub const BOARD_DEFINITION: &str = "board_definition";
    pub const COMPONENT_DEFINITION: &str = "component_definition";
    pub const NET_DEFINITION: &str = "net_definition";
    pub const SIZE_PROPERTY: &str = "size_property";
    pub const LAYERS_PROPERTY: &str = "layers_property";
    pub const VALUE_PROPERTY: &str = "value_property";
    pub const POSITION_PROPERTY: &str = "position_property";
    pub const ROTATION_PROPERTY: &str = "rotation_property";
    pub const PIN_REF: &str = "pin_ref";
    pub const DIMENSION: &str = "dimension";
    pub const IDENTIFIER: &str = "identifier";
    pub const NUMBER: &str = "number";
    pub const STRING: &str = "string";
    pub const ERROR: &str = "ERROR";
}

#[cfg(all(test, feature = "tree-sitter-parser"))]
mod tests {
    use super::*;
    use tree_sitter::Parser;

    fn parse(source: &str) -> tree_sitter::Tree {
        let mut parser = Parser::new();
        parser.set_language(&language()).expect("Failed to set language");
        parser.parse(source, None).expect("Failed to parse")
    }

    #[test]
    fn test_language_loads() {
        let lang = language();
        // Verify the language loaded and has a reasonable number of node kinds
        // (the exact count may change as grammar evolves)
        assert!(lang.node_kind_count() > 50);
    }

    #[test]
    fn test_parse_version() {
        let tree = parse("version 1");
        let root = tree.root_node();
        assert_eq!(root.kind(), "source_file");
        assert!(!root.has_error());

        let version = root.child(0).unwrap();
        assert_eq!(version.kind(), "version_statement");
    }

    #[test]
    fn test_parse_board() {
        let tree = parse(
            r#"
            board test {
                size 30mm x 20mm
                layers 2
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error());

        let board = root.child(0).unwrap();
        assert_eq!(board.kind(), "board_definition");
    }

    #[test]
    fn test_parse_component() {
        let tree = parse(
            r#"
            component R1 resistor "0402" {
                value "330"
                at 10mm, 8mm
                rotate 90
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error());

        let component = root.child(0).unwrap();
        assert_eq!(component.kind(), "component_definition");
    }

    #[test]
    fn test_parse_net() {
        let tree = parse(
            r#"
            net VCC {
                J1.1
                R1.1
                U1.VCC
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error());

        let net = root.child(0).unwrap();
        assert_eq!(net.kind(), "net_definition");
    }

    #[test]
    fn test_parse_complete_example() {
        let tree = parse(
            r#"
            // LED blink circuit
            version 1

            board blink {
                size 30mm x 20mm
                layers 2
            }

            component R1 resistor "0402" {
                value "330"
                at 10mm, 8mm
            }

            component LED1 led "0603" {
                at 15mm, 8mm
            }

            component J1 connector "pin_header_1x2" {
                at 5mm, 8mm
            }

            net VCC {
                J1.1
                R1.1
            }

            net GND {
                J1.2
                LED1.cathode
            }

            net LED_SIGNAL {
                R1.2
                LED1.anode
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error(), "Parse errors: {}", root.to_sexp());
    }

    #[test]
    fn test_error_recovery() {
        // Intentional syntax error: missing closing brace
        let tree = parse("board test { size 10mm x 10mm");
        let root = tree.root_node();
        // Tree-sitter should recover and still produce a tree
        assert!(root.has_error());
        assert_eq!(root.kind(), "source_file");
    }

    #[test]
    fn test_comments() {
        let tree = parse(
            r#"
            // Line comment
            version 1
            /* Block
               comment */
            board test {
                size 10mm x 10mm // inline comment
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error());
    }

    #[test]
    fn test_parse_footprint_definition() {
        let tree = parse(
            r#"
            footprint MY_PKG {
                description "Custom package"
                pad 1 rect at 0mm, 0mm size 1mm x 0.5mm
                pad 2 rect at 2mm, 0mm size 1mm x 0.5mm
                courtyard 4mm x 2mm
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error(), "Parse errors: {}", root.to_sexp());

        let footprint = root.child(0).unwrap();
        assert_eq!(footprint.kind(), "footprint_definition");
    }

    #[test]
    fn test_parse_footprint_with_drill() {
        let tree = parse(
            r#"
            footprint THT_2PIN {
                pad 1 circle at 0mm, 0mm size 1.8mm x 1.8mm drill 1.0mm
                pad 2 circle at 2.54mm, 0mm size 1.8mm x 1.8mm drill 1.0mm
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error(), "Parse errors: {}", root.to_sexp());

        let footprint = root.child(0).unwrap();
        assert_eq!(footprint.kind(), "footprint_definition");
    }

    #[test]
    fn test_parse_footprint_all_pad_shapes() {
        let tree = parse(
            r#"
            footprint ALL_SHAPES {
                pad 1 rect at 0mm, 0mm size 1mm x 1mm
                pad 2 circle at 2mm, 0mm size 1mm x 1mm
                pad 3 roundrect at 4mm, 0mm size 1mm x 1mm
                pad 4 oblong at 6mm, 0mm size 1mm x 2mm
            }
            "#,
        );
        let root = tree.root_node();
        assert!(!root.has_error(), "Parse errors: {}", root.to_sexp());
    }
}

[package]
name = "cypcb-parser"
version.workspace = true
edition.workspace = true
license.workspace = true
description = "Tree-sitter grammar and parser for CodeYourPCB DSL"

[features]
default = ["tree-sitter-parser"]
# Enable tree-sitter parsing (requires C compiler, not WASM compatible)
tree-sitter-parser = ["dep:tree-sitter", "dep:cc"]

[dependencies]
cypcb-core = { workspace = true }
tree-sitter = { workspace = true, optional = true }
miette = { workspace = true }
thiserror = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }

[build-dependencies]
cc = { version = "1.0", optional = true }

// $antlr-format indentWidth 4
// $antlr-format useTab false
// $antlr-format columnLimit 89
// $antlr-format allowShortBlocksOnASingleLine true
// $antlr-format allowShortRulesOnASingleLine false
// $antlr-format alignSemicolons hanging
// $antlr-format alignColons hanging

parser grammar AtoParser;

options {
    superClass = AtoParserBase;
    tokenVocab = AtoLexer;
}

file_input
    : (NEWLINE | stmt)* EOF
    ;

pragma_stmt
    : PRAGMA
    ;

stmt
    : simple_stmts
    | compound_stmt
    | pragma_stmt
    ;
simple_stmts
    : simple_stmt (SEMI_COLON simple_stmt)* SEMI_COLON? NEWLINE
    ;
simple_stmt
    : import_stmt
    | assign_stmt
    | connect_stmt
    | directed_connect_stmt
    | retype_stmt
    | pin_declaration
    | signaldef_stmt
    | assert_stmt
    | declaration_stmt
    | string_stmt
    | pass_stmt
    | trait_stmt
    ;

compound_stmt
    : blockdef
    | for_stmt
    ;

blockdef
    : blocktype type_reference blockdef_super? COLON block
    ;
// TODO @v0.4 consider ()
blockdef_super
    : FROM type_reference
    ;
// TODO @v0.4 consider removing component (or more explicit code-as-data)
blocktype
    : (COMPONENT | MODULE | INTERFACE)
    ;
block
    : simple_stmts
    | NEWLINE INDENT stmt+ DEDENT
    ;

import_stmt
    : (FROM string)? IMPORT type_reference (
        COMMA type_reference
    )*
    ;

declaration_stmt
    : field_reference COLON unit
    ;
field_reference_or_declaration
    : field_reference
    | declaration_stmt
    ;
assign_stmt
    : field_reference_or_declaration '=' assignable
    ;

assignable
    : string
    | new_stmt
    | literal_physical
    | arithmetic_expression
    | boolean_
    ;

retype_stmt
    : field_reference ARROW type_reference
    ;

directed_connect_stmt
    // only one type of SPERM per stmt allowed. both here for better error messages
    : bridgeable (SPERM | LSPERM) (
        bridgeable
        | directed_connect_stmt
    )
    ;
connect_stmt
    : mif WIRE mif
    ;
bridgeable
    : connectable
    ;
mif
    : connectable
    ;
connectable
    : field_reference
    | signaldef_stmt
    | pindef_stmt
    ;

signaldef_stmt
    : SIGNAL name
    ;
pindef_stmt
    : pin_stmt
    ;
pin_declaration
    : pin_stmt
    ;
pin_stmt
    : PIN (name | number_hint_natural | string)
    ;

new_stmt
    : NEW type_reference ('[' new_count ']')? template?
    ;
new_count
    : number_hint_natural
    ;

string_stmt
    : string
    ; // the unbound string is a statement used to add doc-strings

pass_stmt
    : PASS
    ; // the unbound string is a statement used to add doc-strings

list_literal_of_field_references
    : '[' (
        field_reference (COMMA field_reference)* COMMA?
    )? ']'
    ;

iterable_references
    : field_reference slice?
    | list_literal_of_field_references
    ;

for_stmt
    : FOR name IN iterable_references COLON block
    ;

assert_stmt
    : ASSERT comparison
    ;

trait_stmt
    // TODO: move namespacing to type_reference
    : TRAIT field_reference? type_reference (
        DOUBLE_COLON constructor
    )? template?
    ;
constructor
    : name
    ;
template
    : '<' (template_arg (COMMA template_arg)* COMMA?)? '>'
    ;
template_arg
    : name ASSIGN literal
    ;

// Comparison operators --------------------
comparison
    : arithmetic_expression compare_op_pair+
    ;

compare_op_pair
    : lt_arithmetic_or
    | gt_arithmetic_or
    | lt_eq_arithmetic_or
    | gt_eq_arithmetic_or
    | in_arithmetic_or
    | is_arithmetic_or
    ;

lt_arithmetic_or
    : LESS_THAN arithmetic_expression
    ;
gt_arithmetic_or
    : GREATER_THAN arithmetic_expression
    ;
lt_eq_arithmetic_or
    : LT_EQ arithmetic_expression
    ;
gt_eq_arithmetic_or
    : GT_EQ arithmetic_expression
    ;
in_arithmetic_or
    : WITHIN arithmetic_expression
    ;
is_arithmetic_or
    : IS arithmetic_expression
    ;

// Arithmetic operators --------------------

arithmetic_expression
    : arithmetic_expression (OR_OP | AND_OP) sum
    | sum
    ;

sum
    : sum (PLUS | MINUS) term
    | term
    ;

term
    : term (STAR | DIV) power
    | power
    ;

power
    : atom (POWER atom)?
    ;

// Primary elements ----------------

slice
    : '[' (
        slice_start? COLON slice_stop? (COLON slice_step?)?
    )? ']'
    // else [::step] wouldn't match
    | '[' ( DOUBLE_COLON slice_step?) ']'
    ;
slice_start
    : number_hint_integer
    ;
slice_stop
    : number_hint_integer
    ;
slice_step
    : number_hint_integer
    ;

atom
    : field_reference
    | literal_physical
    | arithmetic_group
    ;

arithmetic_group
    : '(' arithmetic_expression ')'
    ;

literal_physical
    : bound_quantity
    | bilateral_quantity
    | quantity
    ;

bound_quantity
    : quantity TO quantity
    ;
bilateral_quantity
    : quantity PLUS_OR_MINUS bilateral_tolerance
    ;
quantity
    : number unit?
    ;
bilateral_tolerance
    : number_signless (PERCENT | unit)?
    ;

key
    : number_hint_integer
    ;
array_index
    : '[' key ']'
    ;

// backwards compatibility for A.1
pin_reference_end
    : DOT number_hint_natural
    ;
field_reference_part
    : name array_index?
    ;
field_reference
    : field_reference_part (DOT field_reference_part)* pin_reference_end?
    ;
type_reference
    : name
    ;
// TODO better unit
unit
    : name
    ;
name
    : NAME
    ;

// Literals
literal
    : string
    | boolean_
    | number
    ;

string
    : STRING
    ;
boolean_
    : TRUE
    | FALSE
    ;
number_hint_natural
    : number_signless
    ;
number_hint_integer
    : number
    ;
number
    : (PLUS | MINUS)? number_signless
    ;
number_signless
    : NUMBER
    ;

lexer grammar AtoLexer;

// All comments that start with "///" are copy-pasted from The Python Language Reference

tokens {
	INDENT,
	DEDENT
}

options {
	superClass = AtoLexerBase;
}

/*
 * lexer rules
 */

STRING: STRING_LITERAL | BYTES_LITERAL;

NUMBER: INTEGER | FLOAT_NUMBER | IMAG_NUMBER;

INTEGER:
	DECIMAL_INTEGER
	| OCT_INTEGER
	| HEX_INTEGER
	| BIN_INTEGER;

COMPONENT: 'component';
MODULE: 'module';
INTERFACE: 'interface';

PIN: 'pin';
SIGNAL: 'signal';

NEW: 'new';
FROM: 'from';
IMPORT: 'import';

FOR: 'for';
IN: 'in';

ASSERT: 'assert';
TO: 'to';

TRUE: 'True';
FALSE: 'False';

WITHIN: 'within';
IS: 'is';
PASS: 'pass';

TRAIT: 'trait';

SPERM: '~>';
LSPERM: '<~';
WIRE: '~';

// Unused but reserved

// TODO: more conservative list
INT: 'int';
FLOAT: 'float';
STRING_: 'string';
STR: 'str';
BYTES: 'bytes';
IF: 'if';
PARAMETER: 'parameter';
PARAM: 'param';
TEST: 'test';
REQUIRE: 'require';
REQUIRES: 'requires';
CHECK: 'check';
REPORT: 'report';
ENSURE: 'ensure';

// Stuff from the Python3 grammer we based this on

/// identifier   ::=  id_start id_continue*
NAME: ID_START ID_CONTINUE*;

STRING_LITERAL: ( SHORT_STRING | LONG_STRING);

BYTES_LITERAL: ( SHORT_BYTES | LONG_BYTES);

/// decimalinteger ::=  nonzerodigit digit* | "0"+
DECIMAL_INTEGER: NON_ZERO_DIGIT DIGIT* | '0'+;

/// octinteger     ::=  "0" ("o" | "O") octdigit+
OCT_INTEGER: '0' [oO] OCT_DIGIT+;

/// hexinteger     ::=  "0" ("x" | "X") hexdigit+
HEX_INTEGER: '0' [xX] HEX_DIGIT+;

/// bininteger     ::=  "0" ("b" | "B") bindigit+
BIN_INTEGER: '0' [bB] BIN_DIGIT+;

/// floatnumber   ::=  pointfloat | exponentfloat
FLOAT_NUMBER: POINT_FLOAT | EXPONENT_FLOAT;

/// imagnumber ::=  (floatnumber | intpart) ("j" | "J")
IMAG_NUMBER: ( FLOAT_NUMBER | INT_PART) [jJ];

PLUS_OR_MINUS: PLUS_SLASH_MINUS | PLUS_MINUS_SIGN;
PLUS_SLASH_MINUS: '+/-';
PLUS_MINUS_SIGN: '\u00B1';

PERCENT: '%';
DOT: '.';
ELLIPSIS: '...';
STAR: '*';
OPEN_PAREN: '(';
CLOSE_PAREN: ')';
COMMA: ',';
DOUBLE_COLON: '::';
COLON: ':';
SEMI_COLON: ';';
POWER: '**';
ASSIGN: '=';
OPEN_BRACK: '[';
CLOSE_BRACK: ']';
OR_OP: '|';
XOR: '^';
AND_OP: '&';
LEFT_SHIFT: '<<';
RIGHT_SHIFT: '>>';
PLUS: '+';
MINUS: '-';
DIV: '/';
IDIV: '//';
// NOT_OP: '~';  // conflicts with connect
OPEN_BRACE: '{';
CLOSE_BRACE: '}';
LESS_THAN: '<';
GREATER_THAN: '>';
EQUALS: '==';
GT_EQ: '>=';
LT_EQ: '<=';
NOT_EQ_1: '<>';
NOT_EQ_2: '!=';
AT: '@';
ARROW: '->';

// From Python3.12 lexer example credit Robert Einhorn (MIT License)
// https://github.com/antlr/grammars-v4/blob/6d13b1068d0fc9eba30a3f291fe62026fbc71c2f/python/python3_12/PythonLexer.g4#L169
// https://docs.python.org/3.12/reference/lexical_analysis.html#physical-lines
NEWLINE: '\r'? '\n'; // Unix, Windows

PRAGMA:
	'#pragma' ~[\r\n]*; // Keep on default channel (pre-comment)
// https://docs.python.org/3.12/reference/lexical_analysis.html#comments
COMMENT: '#' ~[\r\n]* -> channel(HIDDEN);

// https://docs.python.org/3.12/reference/lexical_analysis.html#whitespace-between-tokens
WS: [ \t\f]+ -> channel(HIDDEN);

// https://docs.python.org/3.12/reference/lexical_analysis.html#explicit-line-joining
EXPLICIT_LINE_JOINING: '\\' NEWLINE -> channel(HIDDEN);

ERRORTOKEN:
	.; // catch the unrecognized characters and redirect these errors to the parser

/*
 * fragments
 */

/// shortstring ::= "'" shortstringitem* "'" | '"' shortstringitem* '"' / shortstringitem ::=
// shortstringchar | stringescapeseq / shortstringchar ::= <any source character except "\" or
// newline or the quote>
fragment SHORT_STRING:
	'\'' (STRING_ESCAPE_SEQ | ~[\\\r\n\f'])* '\''
	| '"' ( STRING_ESCAPE_SEQ | ~[\\\r\n\f"])* '"';
/// longstring      ::=  "'''" longstringitem* "'''" | '"""' longstringitem* '"""'
fragment LONG_STRING:
	'\'\'\'' LONG_STRING_ITEM*? '\'\'\''
	| '"""' LONG_STRING_ITEM*? '"""';

/// longstringitem  ::=  longstringchar | stringescapeseq
fragment LONG_STRING_ITEM: LONG_STRING_CHAR | STRING_ESCAPE_SEQ;

/// longstringchar  ::=  <any source character except "\">
fragment LONG_STRING_CHAR: ~'\\';

/// stringescapeseq ::=  "\" <any source character>
fragment STRING_ESCAPE_SEQ: '\\' . | '\\' NEWLINE;

/// nonzerodigit   ::=  "1"..."9"
fragment NON_ZERO_DIGIT: [1-9];

/// digit          ::=  "0"..."9"
fragment DIGIT: [0-9];

/// octdigit       ::=  "0"..."7"
fragment OCT_DIGIT: [0-7];

/// hexdigit       ::=  digit | "a"..."f" | "A"..."F"
fragment HEX_DIGIT: [0-9a-fA-F];

/// bindigit       ::=  "0" | "1"
fragment BIN_DIGIT: [01];

/// pointfloat    ::=  [intpart] fraction | intpart "."
fragment POINT_FLOAT: INT_PART '.' INT_PART;

/// exponentfloat ::=  (intpart | pointfloat) exponent
fragment EXPONENT_FLOAT: ( INT_PART | POINT_FLOAT) EXPONENT;

/// intpart       ::=  digit+
fragment INT_PART: DIGIT+;

// /// fraction ::= "." digit+ fragment FRACTION : '.' DIGIT+ ;

/// exponent      ::=  ("e" | "E") ["+" | "-"] digit+
fragment EXPONENT: [eE] [+-]? DIGIT+;

/// shortbytes ::= "'" shortbytesitem* "'" | '"' shortbytesitem* '"' / shortbytesitem ::=
// shortbyteschar | bytesescapeseq
fragment SHORT_BYTES:
	'\'' (SHORT_BYTES_CHAR_NO_SINGLE_QUOTE | BYTES_ESCAPE_SEQ)* '\''
	| '"' (SHORT_BYTES_CHAR_NO_DOUBLE_QUOTE | BYTES_ESCAPE_SEQ)* '"';

/// longbytes      ::=  "'''" longbytesitem* "'''" | '"""' longbytesitem* '"""'
fragment LONG_BYTES:
	'\'\'\'' LONG_BYTES_ITEM*? '\'\'\''
	| '"""' LONG_BYTES_ITEM*? '"""';

/// longbytesitem  ::=  longbyteschar | bytesescapeseq
fragment LONG_BYTES_ITEM: LONG_BYTES_CHAR | BYTES_ESCAPE_SEQ;

/// shortbyteschar ::=  <any ASCII character except "\" or newline or the quote>
fragment SHORT_BYTES_CHAR_NO_SINGLE_QUOTE:
	[\u0000-\u0009]
	| [\u000B-\u000C]
	| [\u000E-\u0026]
	| [\u0028-\u005B]
	| [\u005D-\u007F];

fragment SHORT_BYTES_CHAR_NO_DOUBLE_QUOTE:
	[\u0000-\u0009]
	| [\u000B-\u000C]
	| [\u000E-\u0021]
	| [\u0023-\u005B]
	| [\u005D-\u007F];

/// longbyteschar  ::=  <any ASCII character except "\">
fragment LONG_BYTES_CHAR: [\u0000-\u005B] | [\u005D-\u007F];

/// bytesescapeseq ::=  "\" <any ASCII character>
fragment BYTES_ESCAPE_SEQ: '\\' [\u0000-\u007F];

fragment SPACES: [ \t]+;

fragment LINE_JOINING: '\\' SPACES? ( '\r'? '\n' | '\r' | '\f');

// TODO: ANTLR seems lack of some Unicode property support... $ curl
// https://www.unicode.org/Public/13.0.0/ucd/PropList.txt | grep Other_ID_ 1885..1886 ;
// Other_ID_Start # Mn [2] MONGOLIAN LETTER ALI GALI BALUDA..MONGOLIAN LETTER ALI GALI THREE BALUDA
// 2118 ; Other_ID_Start # Sm SCRIPT CAPITAL P 212E ; Other_ID_Start # So ESTIMATED SYMBOL
// 309B..309C ; Other_ID_Start # Sk [2] KATAKANA-HIRAGANA VOICED SOUND MARK..KATAKANA-HIRAGANA
// SEMI-VOICED SOUND MARK 00B7 ; Other_ID_Continue # Po MIDDLE DOT 0387 ; Other_ID_Continue # Po
// GREEK ANO TELEIA 1369..1371 ; Other_ID_Continue # No [9] ETHIOPIC DIGIT ONE..ETHIOPIC DIGIT NINE
// 19DA ; Other_ID_Continue # No NEW TAI LUE THAM DIGIT ONE

fragment UNICODE_OIDS:
	'\u1885' ..'\u1886'
	| '\u2118'
	| '\u212e'
	| '\u309b' ..'\u309c';

fragment UNICODE_OIDC:
	'\u00b7'
	| '\u0387'
	| '\u1369' ..'\u1371'
	| '\u19da';

/// id_start     ::=  <all characters in general categories Lu, Ll, Lt, Lm, Lo, Nl, the underscore, and characters with the Other_ID_Start property>
fragment ID_START:
	'_'
	| [\p{L}]
	| [\p{Nl}]
	//| [\p{Other_ID_Start}]
	| UNICODE_OIDS;

/// id_continue  ::=  <all characters in id_start, plus characters in the categories Mn, Mc, Nd, Pc and others with the Other_ID_Continue property>
fragment ID_CONTINUE:
	ID_START
	| [\p{Mn}]
	| [\p{Mc}]
	| [\p{Nd}]
	| [\p{Pc}]
	//| [\p{Other_ID_Continue}]
	| UNICODE_OIDC;

//! Unit types for dimension parsing.
//!
//! This module provides the [`Unit`] enum for representing and converting
//! between different measurement units used in PCB design.

use crate::coords::{Nm, NM_PER_INCH, NM_PER_MIL, NM_PER_MM};
use serde::{Deserialize, Serialize};
use std::str::FromStr;
use thiserror::Error;

/// A unit of measurement for PCB dimensions.
///
/// Used for parsing dimensions from the DSL and converting to internal
/// nanometer representation.
///
/// # Examples
///
/// ```
/// use cypcb_core::{Unit, Nm};
///
/// let unit = Unit::Mm;
/// let nm = unit.to_nm(10.0);
/// assert_eq!(nm.0, 10_000_000);
/// ```
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Unit {
    /// Millimeters (1 mm = 1,000,000 nm)
    #[default]
    Mm,
    /// Mils / thousandths of an inch (1 mil = 25,400 nm)
    Mil,
    /// Inches (1 inch = 25,400,000 nm)
    Inch,
    /// Nanometers (native unit)
    Nm,
}

impl Unit {
    /// Convert a value in this unit to nanometers.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
    /// assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
    /// assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
    /// assert_eq!(Unit::Nm.to_nm(100.0).0, 100);
    /// ```
    #[inline]
    pub fn to_nm(self, value: f64) -> Nm {
        let nm = match self {
            Unit::Mm => (value * NM_PER_MM as f64).round() as i64,
            Unit::Mil => (value * NM_PER_MIL as f64).round() as i64,
            Unit::Inch => (value * NM_PER_INCH as f64).round() as i64,
            Unit::Nm => value.round() as i64,
        };
        Nm(nm)
    }

    /// Convert a nanometer value to this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::{Unit, Nm};
    ///
    /// let nm = Nm(1_000_000);
    /// assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);
    /// ```
    #[inline]
    pub fn from_nm(self, nm: Nm) -> f64 {
        match self {
            Unit::Mm => nm.0 as f64 / NM_PER_MM as f64,
            Unit::Mil => nm.0 as f64 / NM_PER_MIL as f64,
            Unit::Inch => nm.0 as f64 / NM_PER_INCH as f64,
            Unit::Nm => nm.0 as f64,
        }
    }

    /// Get the suffix string for this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.suffix(), "mm");
    /// assert_eq!(Unit::Mil.suffix(), "mil");
    /// ```
    pub const fn suffix(self) -> &'static str {
        match self {
            Unit::Mm => "mm",
            Unit::Mil => "mil",
            Unit::Inch => "in",
            Unit::Nm => "nm",
        }
    }

    /// Get the nanometers per unit.
    ///
    /// Returns 1 for nanometers.
    pub const fn nm_per_unit(self) -> i64 {
        match self {
            Unit::Mm => NM_PER_MM,
            Unit::Mil => NM_PER_MIL,
            Unit::Inch => NM_PER_INCH,
            Unit::Nm => 1,
        }
    }
}



impl std::fmt::Display for Unit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.suffix())
    }
}

/// Error type for unit parsing.
#[derive(Debug, Clone, Error, PartialEq, Eq)]
#[error("unknown unit: '{0}' (expected: mm, mil, in, nm)")]
pub struct ParseUnitError(pub String);

impl FromStr for Unit {
    type Err = ParseUnitError;

    /// Parse a unit from a string.
    ///
    /// Accepts: "mm", "mil", "in", "inch", "nm"
    /// Case-insensitive.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
    /// assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
    /// assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    ///
    /// // Case insensitive
    /// assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
    /// ```
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "mm" => Ok(Unit::Mm),
            "mil" | "mils" => Ok(Unit::Mil),
            "in" | "inch" | "inches" => Ok(Unit::Inch),
            "nm" => Ok(Unit::Nm),
            _ => Err(ParseUnitError(s.to_string())),
        }
    }
}

/// A dimension value with an associated unit.
///
/// This is useful for preserving the original unit in the source
/// while still being able to convert to nanometers.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Dimension {
    /// The numeric value in the original unit.
    pub value: f64,
    /// The unit of measurement.
    pub unit: Unit,
}

impl Dimension {
    /// Create a new dimension.
    pub const fn new(value: f64, unit: Unit) -> Self {
        Dimension { value, unit }
    }

    /// Create a dimension in millimeters.
    pub const fn mm(value: f64) -> Self {
        Dimension { value, unit: Unit::Mm }
    }

    /// Create a dimension in mils.
    pub const fn mil(value: f64) -> Self {
        Dimension { value, unit: Unit::Mil }
    }

    /// Create a dimension in inches.
    pub const fn inch(value: f64) -> Self {
        Dimension { value, unit: Unit::Inch }
    }

    /// Create a dimension in nanometers.
    pub const fn nm(value: f64) -> Self {
        Dimension { value, unit: Unit::Nm }
    }

    /// Convert this dimension to nanometers.
    pub fn to_nm(self) -> Nm {
        self.unit.to_nm(self.value)
    }
}

impl std::fmt::Display for Dimension {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{}", self.value, self.unit)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_unit_to_nm() {
        assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
        assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
        assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
        assert_eq!(Unit::Nm.to_nm(1.0).0, 1);
    }

    #[test]
    fn test_unit_from_nm() {
        let nm = Nm(1_000_000);
        assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400);
        assert!((Unit::Mil.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400_000);
        assert!((Unit::Inch.from_nm(nm) - 1.0).abs() < 1e-9);
    }

    #[test]
    fn test_unit_round_trip() {
        for unit in [Unit::Mm, Unit::Mil, Unit::Inch] {
            let original = 10.5;
            let nm = unit.to_nm(original);
            let back = unit.from_nm(nm);
            assert!((back - original).abs() < 0.001, "Round-trip failed for {:?}", unit);
        }
    }

    #[test]
    fn test_unit_parse() {
        assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("mils".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inches".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    }

    #[test]
    fn test_unit_parse_error() {
        let result = "cm".parse::<Unit>();
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().0, "cm");
    }

    #[test]
    fn test_dimension_to_nm() {
        let dim = Dimension::mm(10.0);
        assert_eq!(dim.to_nm().0, 10_000_000);

        let dim = Dimension::mil(100.0);
        assert_eq!(dim.to_nm().0, 2_540_000);
    }

    #[test]
    fn test_unit_suffix() {
        assert_eq!(Unit::Mm.suffix(), "mm");
        assert_eq!(Unit::Mil.suffix(), "mil");
        assert_eq!(Unit::Inch.suffix(), "in");
        assert_eq!(Unit::Nm.suffix(), "nm");
    }
}

//! CodeYourPCB Core
//!
//! Shared types, coordinates, and geometry primitives for the CodeYourPCB system.
//! All coordinates use integer nanometers (i64) for deterministic precision.
//!
//! # Why Integer Nanometers?
//!
//! PCB tools commonly face issues with floating-point accumulation errors.
//! Small precision errors compound across complex routing operations, leading to:
//! - Traces that should connect but don't (off by sub-micron amounts)
//! - Non-deterministic DRC results
//! - Different output from the same input file
//!
//! By using i64 nanometers internally:
//! - All coordinate arithmetic is exact
//! - Same input always produces identical output
//! - Comparisons and hashing are reliable
//! - Range is sufficient (i64 max = ~9.2 billion meters)
//!
//! # Coordinate System
//!
//! - Origin: bottom-left of the board
//! - X-axis: positive right
//! - Y-axis: positive up (mathematical convention)
//!
//! This matches standard mathematical conventions and most Gerber viewers.
//!
//! # Unit Conversions
//!
//! | Unit | Nanometers |
//! |------|------------|
//! | 1 mm | 1,000,000 |
//! | 1 mil | 25,400 |
//! | 1 inch | 25,400,000 |
//!
//! # Modules
//!
//! - [`coords`]: Core coordinate types ([`Nm`], [`Point`])
//! - [`units`]: Unit parsing and conversion ([`Unit`])
//! - [`geometry`]: Geometric primitives ([`Rect`])

pub mod coords;
pub mod geometry;
pub mod units;

// Re-export primary types at crate root for convenience
pub use coords::{Nm, Point, NM_PER_INCH, NM_PER_MIL, NM_PER_MM};
pub use geometry::Rect;
pub use units::{Dimension, ParseUnitError, Unit};

//! Routing rule trait for the A*-based autorouter.
//!
//! [`RoutingRuleSet`] is the primary interface between the design rules system
//! and the routing engine. It must be object-safe so it can be stored as
//! `dyn RoutingRuleSet` in the router.
//!
//! # Layer indices
//!
//! This module uses `u8` layer indices instead of importing `cypcb-world`'s
//! `Layer` enum, keeping `cypcb-rules` as a leaf crate. Convention:
//! - 0 = top copper
//! - 1 = inner-1
//! - N = bottom copper (where N = total_copper_layers - 1)

use crate::constraints::DesignConstraints;
use crate::signal_class::{SignalClass, SignalClassConstraints};
use cypcb_core::Nm;

/// Rule set interface for routing and DRC engines.
///
/// This trait is designed to be object-safe (`dyn RoutingRuleSet` compiles).
/// All methods take `&self` and return owned or reference types — no generics,
/// no `Self`-returning methods.
///
/// # For autorouter integration
///
/// The A* router uses:
/// - [`constraints_for_net`](RoutingRuleSet::constraints_for_net) to get per-net clearances and widths
/// - [`via_cost`](RoutingRuleSet::via_cost) to penalize layer transitions
/// - [`layer_change_cost`](RoutingRuleSet::layer_change_cost) to bias routing toward preferred layers
/// - [`clearance_between`](RoutingRuleSet::clearance_between) to check spacing between different nets
///
/// # Examples
///
/// ```
/// use cypcb_rules::{RoutingRuleSet, DesignConstraints, SignalClass, SignalClassConstraints};
/// use cypcb_core::Nm;
///
/// struct SimpleRules {
///     constraints: DesignConstraints,
/// }
///
/// impl RoutingRuleSet for SimpleRules {
///     fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
///         &self.constraints
///     }
///
///     fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
///         class.default_constraints()
///     }
///
///     fn via_cost(&self, _from_layer: u8, _to_layer: u8) -> f64 {
///         1.0
///     }
///
///     fn layer_change_cost(&self, _layer: u8) -> f64 {
///         0.5
///     }
///
///     fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
///         self.constraints.min_clearance
///     }
/// }
///
/// let rules = SimpleRules { constraints: DesignConstraints::default() };
/// let _: &dyn RoutingRuleSet = &rules; // object-safe
/// ```
pub trait RoutingRuleSet {
    /// Get the design constraints applicable to a specific net.
    ///
    /// For simple designs, this may return the same constraints for all nets.
    /// Advanced designs may have per-net overrides.
    fn constraints_for_net(&self, net_id: u32) -> &DesignConstraints;

    /// Get the signal-class-specific constraints.
    ///
    /// Returns an owned [`SignalClassConstraints`] because classes may be
    /// computed dynamically.
    fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints;

    /// Cost of placing a via transitioning between two layers.
    ///
    /// Higher values discourage the router from adding vias. Typical range:
    /// - 0.5–2.0 for standard vias
    /// - 5.0+ for blind/buried vias (more expensive to fabricate)
    /// - `f64::INFINITY` to prohibit a transition entirely
    fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64;

    /// Cost of routing on a specific layer.
    ///
    /// Used by the A* router to bias routing toward preferred layers.
    /// Lower values = preferred. Typical range: 0.1–2.0.
    fn layer_change_cost(&self, layer: u8) -> f64;

    /// Minimum clearance required between two specific nets.
    ///
    /// Allows net-pair-specific spacing rules (e.g. high-voltage isolation
    /// between power nets and signal nets).
    fn clearance_between(&self, net_a: u32, net_b: u32) -> Nm;
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Minimal implementation to verify the trait is object-safe and usable.
    struct TestRules {
        base: DesignConstraints,
    }

    impl TestRules {
        fn new() -> Self {
            Self {
                base: DesignConstraints::default(),
            }
        }
    }

    impl RoutingRuleSet for TestRules {
        fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
            &self.base
        }

        fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
            class.default_constraints()
        }

        fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64 {
            let span = (from_layer as i16 - to_layer as i16).unsigned_abs() as f64;
            span * 0.5
        }

        fn layer_change_cost(&self, layer: u8) -> f64 {
            if layer == 0 { 0.1 } else { 1.0 }
        }

        fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
            self.base.min_clearance
        }
    }

    #[test]
    fn test_trait_object_safe() {
        let rules = TestRules::new();
        // This line proves object safety — if it compiles, dyn dispatch works.
        let dyn_rules: &dyn RoutingRuleSet = &rules;
        let c = dyn_rules.constraints_for_net(0);
        assert_eq!(c.min_clearance, DesignConstraints::default().min_clearance);
    }

    #[test]
    fn test_via_cost_scales_with_span() {
        let rules = TestRules::new();
        let cost_1 = rules.via_cost(0, 1);
        let cost_2 = rules.via_cost(0, 2);
        assert!(cost_2 > cost_1, "Multi-layer via should cost more");
    }

    #[test]
    fn test_layer_change_cost() {
        let rules = TestRules::new();
        assert!(rules.layer_change_cost(0) < rules.layer_change_cost(1));
    }

    #[test]
    fn test_clearance_between_returns_nm() {
        let rules = TestRules::new();
        let clearance = rules.clearance_between(1, 2);
        assert!(clearance.raw() > 0);
    }

    #[test]
    fn test_constraints_for_class() {
        let rules = TestRules::new();
        let dyn_rules: &dyn RoutingRuleSet = &rules;
        let power = dyn_rules.constraints_for_class(SignalClass::Power);
        let digital = dyn_rules.constraints_for_class(SignalClass::Digital);
        assert!(power.min_trace_width.raw() > digital.min_trace_width.raw());
    }

    #[test]
    fn test_dyn_dispatch_all_methods() {
        let rules = TestRules::new();
        let dyn_rules: &dyn RoutingRuleSet = &rules;

        // Exercise every trait method through dyn dispatch
        let _ = dyn_rules.constraints_for_net(42);
        let _ = dyn_rules.constraints_for_class(SignalClass::HighSpeed);
        let _ = dyn_rules.via_cost(0, 3);
        let _ = dyn_rules.layer_change_cost(1);
        let _ = dyn_rules.clearance_between(10, 20);
    }
}

//! PCB design constraints covering all fabrication parameters.
//!
//! [`DesignConstraints`] is the central configuration struct that defines the
//! manufacturing limits and design rules for a PCB. All dimension fields use
//! [`Nm`] for type-safe, integer-precision measurements.
//!
//! The [`Default`] implementation provides values matching JLCPCB's 2-layer
//! standard process capabilities.

use cypcb_core::Nm;
use serde::{Deserialize, Serialize};

/// Comprehensive PCB design constraints.
///
/// Organized by category:
/// - **Basic geometry**: fundamental clearances and minimums
/// - **Advanced geometry**: via details, drill aspect ratios, solder mask
/// - **Signal integrity**: impedance, differential pairs, length matching
/// - **Thermal**: current capacity, thermal relief, copper pour
/// - **Manufacturing**: board construction, hole spacing, via types
///
/// All dimension fields use [`Nm`]. Non-dimension fields (impedance in ohms,
/// ratios, weights) use appropriate numeric types.
///
/// # Examples
///
/// ```
/// use cypcb_rules::DesignConstraints;
/// use cypcb_core::Nm;
///
/// let dc = DesignConstraints::default();
/// // JLCPCB 2-layer minimum trace width: 0.127mm (5 mil)
/// assert_eq!(dc.min_trace_width, Nm::from_mm(0.127));
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DesignConstraints {
    // ── Basic geometry ──────────────────────────────────────────────

    /// Minimum clearance between copper features on the same layer.
    pub min_clearance: Nm,
    /// Minimum trace (track) width.
    pub min_trace_width: Nm,
    /// Minimum finished drill hole diameter.
    pub min_drill_size: Nm,
    /// Minimum via drill hole diameter.
    pub min_via_drill: Nm,
    /// Minimum annular ring around pads.
    pub min_annular_ring: Nm,
    /// Minimum silkscreen line width.
    pub min_silk_width: Nm,
    /// Minimum clearance from copper to board edge.
    pub min_edge_clearance: Nm,

    // ── Advanced geometry ───────────────────────────────────────────

    /// Minimum annular ring around vias (may differ from pad annular ring).
    pub min_via_annular_ring: Nm,
    /// Maximum drill aspect ratio (depth:diameter). Stored as ratio × 100
    /// to keep integer precision (e.g. 600 = 6.0:1).
    pub max_drill_aspect_ratio: u32,
    /// Minimum solder mask bridge (dam) between adjacent mask openings.
    pub min_solder_mask_bridge: Nm,
    /// Minimum clearance between paste stencil openings.
    pub min_paste_clearance: Nm,
    /// Solder mask expansion beyond the pad.
    pub solder_mask_expansion: Nm,
    /// Minimum pad size (diameter for round, short axis for oblong).
    pub min_pad_size: Nm,
    /// Minimum copper-to-slot clearance.
    pub min_slot_clearance: Nm,

    // ── Signal integrity ────────────────────────────────────────────

    /// Default target impedance (ohms × 100 for integer precision, e.g. 5000 = 50.00 Ω).
    pub default_impedance_ohms_x100: u32,
    /// Differential pair gap (space between traces).
    pub diff_pair_gap: Nm,
    /// Differential pair width tolerance.
    pub diff_pair_tolerance: Nm,
    /// Maximum stub length for high-speed signals.
    pub max_stub_length: Nm,
    /// Length-matching tolerance for matched-length groups.
    pub length_match_tolerance: Nm,
    /// Maximum allowed via count in a high-speed signal path.
    pub max_vias_per_high_speed_net: u32,

    // ── Thermal ─────────────────────────────────────────────────────

    /// Maximum current per unit width (mA per mm × 100, e.g. 100_000 = 1000.00 mA/mm).
    /// Based on IPC-2152 for 10°C rise, 1oz copper, outer layer.
    pub max_current_per_width_x100: u32,
    /// Thermal relief gap width.
    pub thermal_relief_gap: Nm,
    /// Thermal relief spoke width.
    pub thermal_relief_spoke_width: Nm,
    /// Minimum clearance between copper pour and other copper features.
    pub min_copper_pour_clearance: Nm,
    /// Number of thermal relief spokes (typically 2 or 4).
    pub thermal_relief_spokes: u8,

    // ── Manufacturing ───────────────────────────────────────────────

    /// Copper weight in oz/ft² × 10 (e.g. 10 = 1.0 oz).
    pub copper_weight_oz_x10: u32,
    /// Total board thickness.
    pub board_thickness: Nm,
    /// Minimum hole-to-hole spacing (edge to edge).
    pub min_hole_to_hole: Nm,
    /// Minimum hole-to-board-edge spacing.
    pub min_hole_to_edge: Nm,
    /// Whether blind vias are allowed in this design.
    pub blind_vias_allowed: bool,
    /// Whether buried vias are allowed in this design.
    pub buried_vias_allowed: bool,
    /// Minimum copper feature size for acid trap avoidance.
    pub min_acid_trap: Nm,
    /// Maximum number of copper layers supported.
    pub max_copper_layers: u8,
    /// Whether castellated holes are allowed.
    pub castellated_holes_allowed: bool,
}

impl DesignConstraints {
    /// Number of constraint fields in the struct.
    /// Used for verification that the struct has 30+ fields.
    pub const FIELD_COUNT: usize = 35;
}

impl Default for DesignConstraints {
    /// JLCPCB 2-layer standard process defaults.
    ///
    /// Source: JLCPCB capabilities page (2-layer, standard process).
    /// Values represent minimum capabilities, not recommended values.
    fn default() -> Self {
        Self {
            // Basic geometry
            min_clearance: Nm::from_mm(0.127),            // 5 mil
            min_trace_width: Nm::from_mm(0.127),           // 5 mil
            min_drill_size: Nm::from_mm(0.3),              // 0.3mm min drill
            min_via_drill: Nm::from_mm(0.3),               // 0.3mm min via drill
            min_annular_ring: Nm::from_mm(0.127),          // 5 mil
            min_silk_width: Nm::from_mm(0.15),             // 0.15mm silk
            min_edge_clearance: Nm::from_mm(0.3),          // 0.3mm to edge

            // Advanced geometry
            min_via_annular_ring: Nm::from_mm(0.127),      // 5 mil
            max_drill_aspect_ratio: 800,                    // 8:1
            min_solder_mask_bridge: Nm::from_mm(0.1),      // 0.1mm
            min_paste_clearance: Nm::from_mm(0.127),       // 5 mil
            solder_mask_expansion: Nm::from_mm(0.05),      // 0.05mm typical
            min_pad_size: Nm::from_mm(0.5),                // 0.5mm min pad
            min_slot_clearance: Nm::from_mm(0.3),          // 0.3mm

            // Signal integrity
            default_impedance_ohms_x100: 5000,              // 50.00 Ω
            diff_pair_gap: Nm::from_mm(0.127),             // 5 mil
            diff_pair_tolerance: Nm::from_mm(0.025),       // 25µm
            max_stub_length: Nm::from_mm(1.0),             // 1mm
            length_match_tolerance: Nm::from_mm(0.5),      // 0.5mm
            max_vias_per_high_speed_net: 4,

            // Thermal
            max_current_per_width_x100: 100_000,            // 1000 mA/mm
            thermal_relief_gap: Nm::from_mm(0.254),        // 10 mil
            thermal_relief_spoke_width: Nm::from_mm(0.254), // 10 mil
            min_copper_pour_clearance: Nm::from_mm(0.254), // 10 mil
            thermal_relief_spokes: 4,

            // Manufacturing
            copper_weight_oz_x10: 10,                       // 1.0 oz
            board_thickness: Nm::from_mm(1.6),             // 1.6mm standard
            min_hole_to_hole: Nm::from_mm(0.5),            // 0.5mm
            min_hole_to_edge: Nm::from_mm(0.3),            // 0.3mm
            blind_vias_allowed: false,
            buried_vias_allowed: false,
            min_acid_trap: Nm::from_mm(0.127),             // 5 mil
            max_copper_layers: 2,
            castellated_holes_allowed: false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_default_has_jlcpcb_values() {
        let dc = DesignConstraints::default();

        // JLCPCB 2-layer: 5mil min trace
        assert_eq!(dc.min_trace_width, Nm::from_mm(0.127));
        // JLCPCB 2-layer: 5mil min clearance
        assert_eq!(dc.min_clearance, Nm::from_mm(0.127));
        // Standard board thickness
        assert_eq!(dc.board_thickness, Nm::from_mm(1.6));
        // 1oz copper
        assert_eq!(dc.copper_weight_oz_x10, 10);
        // No blind/buried vias on 2-layer
        assert!(!dc.blind_vias_allowed);
        assert!(!dc.buried_vias_allowed);
        // 2 copper layers
        assert_eq!(dc.max_copper_layers, 2);
    }

    #[test]
    fn test_default_drill_sizes() {
        let dc = DesignConstraints::default();
        assert_eq!(dc.min_drill_size, Nm::from_mm(0.3));
        assert_eq!(dc.min_via_drill, Nm::from_mm(0.3));
    }

    #[test]
    fn test_field_count_at_least_30() {
        // Compile-time verified: DesignConstraints::FIELD_COUNT = 35
        assert!(DesignConstraints::FIELD_COUNT >= 30);
    }

    #[test]
    fn test_constraints_clone_eq() {
        let dc1 = DesignConstraints::default();
        let dc2 = dc1.clone();
        assert_eq!(dc1, dc2);
    }

    #[test]
    fn test_all_dimensions_use_nm() {
        let dc = DesignConstraints::default();
        // Spot-check that dimension fields are Nm, not raw numbers.
        // If any of these fail to compile, a field was changed away from Nm.
        let _: Nm = dc.min_clearance;
        let _: Nm = dc.min_trace_width;
        let _: Nm = dc.min_drill_size;
        let _: Nm = dc.min_via_drill;
        let _: Nm = dc.min_annular_ring;
        let _: Nm = dc.min_silk_width;
        let _: Nm = dc.min_edge_clearance;
        let _: Nm = dc.thermal_relief_gap;
        let _: Nm = dc.board_thickness;
        let _: Nm = dc.diff_pair_gap;
        let _: Nm = dc.length_match_tolerance;
    }

    #[test]
    fn test_constraints_serde_roundtrip() {
        let dc = DesignConstraints::default();
        let json = serde_json::to_string(&dc).unwrap();
        let dc2: DesignConstraints = serde_json::from_str(&json).unwrap();
        assert_eq!(dc, dc2);
    }

    #[test]
    fn test_edge_clearance_positive() {
        let dc = DesignConstraints::default();
        assert!(dc.min_edge_clearance.raw() > 0);
        assert!(dc.min_hole_to_edge.raw() > 0);
    }
}

// Complete 555 Timer LED Blink Circuit
// NE555 in astable mode, ~1.4 Hz blink
// Supply: 5V via 2-pin header
version 1

board blink {
    size 60mm x 40mm
    layers 2
}

component J1 connector "PIN-HDR-1x2" {
    value "5V PWR"
    at 5mm, 20mm
}

component U1 ic "SOIC-8" {
    value "NE555"
    at 28mm, 20mm
}

// Timing: f = 1.44 / ((R1 + 2*R2) * C1) ≈ 1.4 Hz
component R1 resistor "0402" {
    value "10k"
    at 35mm, 30mm
}

component R2 resistor "0402" {
    value "47k"
    at 35mm, 24mm
}

component C1 capacitor "1206" {
    value "10uF"
    at 43mm, 20mm
}

component C2 capacitor "0402" {
    value "100nF"
    at 22mm, 13mm
}

component C3 capacitor "0402" {
    value "100nF"
    at 22mm, 27mm
}

component R3 resistor "0402" {
    value "470R"
    at 50mm, 20mm
}

component LED1 led "0805" {
    value "RED"
    at 55mm, 20mm
}

net VCC {
    J1.1
    U1.8
    U1.4
    R1.1
    C3.1
}

net GND {
    J1.2
    U1.1
    C1.2
    C2.2
    C3.2
    LED1.K
}

net DIS {
    U1.7
    R1.2
    R2.1
}

net TRG_THR {
    U1.2
    U1.6
    R2.2
    C1.1
}

net CV {
    U1.5
    C2.1
}

net OUT {
    U1.3
    R3.1
}

net LED_ANODE {
    R3.2
    LED1.A
}

// Najprostszy zasilacz 5V
// Wejście: 7-12V DC
