### Define Tree-sitter Grammar with Extras, Conflicts, and Precedences (JavaScript)

Source: https://context7.com/tree-sitter/tree-sitter/llms.txt

This JavaScript code defines a Tree-sitter grammar. It includes sections for 'extras' to define tokens like whitespace and comments that can appear anywhere, 'conflicts' to explicitly handle ambiguities for parsers like GLR, and 'precedences' to establish operator precedence levels. It also defines various grammar rules for statements, expressions, and tokens.

```javascript
module.exports = grammar({
    name: 'advanced_lang',

    // Tokens that can appear anywhere in the grammar
    extras: $ => [
        /\s/,           // Whitespace
        $.comment,      // Comments
    ],

    // Explicit conflicts for GLR parsing
    conflicts: $ => [
        // Type annotations vs comparisons: "x < y" could be either
        [$.type_arguments, $.binary_expression],
    ],

    // Named precedence levels (highest to lowest)
    precedences: $ => [
        ['call', 'unary', 'binary_times', 'binary_plus', 'comparison'],
    ],

    // Keyword extraction for better error recovery
    word: $ => $.identifier,

    // Supertype nodes for grouping
    supertypes: $ => [
        $._expression,
        $._statement,
    ],

    rules: {
        source_file: $ => repeat($._statement),

        _statement: $ => choice(
            $.expression_statement,
            $.if_statement,
        ),

        if_statement: $ => seq(
            'if',
            field('condition', $._expression),
            field('consequence', $.block),
            optional(seq('else', field('alternative', $.block)))
        ),

        expression_statement: $ => seq($._expression, ';'),

        _expression: $ => choice(
            $.identifier,
            $.number,
            $.unary_expression,
            $.binary_expression,
            $.call_expression,
        ),

        // Using named precedence
        unary_expression: $ => prec('unary', seq(
            choice('-', '!'),
            $._expression,
        )),

        binary_expression: $ => choice(
            prec.left('binary_times', seq($._expression, choice('*', '/'), $._expression)),
            prec.left('binary_plus', seq($._expression, choice('+', '-'), $._expression)),
            prec.left('comparison', seq($._expression, choice('<', '>', '=='), $._expression))
        ),

        call_expression: $ => prec('call', seq(
            field('function', $._expression),
            '(' ,
            optional($.argument_list),
            ')'
        )),

        // For the type_arguments conflict
        type_arguments: $ => seq('<', $.identifier, '>'),

        argument_list: $ => seq(
            $._expression,
            repeat(seq(',', $._expression))
        ),

        block: $ => seq('{', repeat($._statement), '}'),

        comment: $ => token(choice(
            seq('//', /.*/),
            seq('/*', /[^*]**+([^/*][^*]**+)*/, '/')
        )),

        identifier: $ => /[a-zA-Z_][a-zA-Z0-9_]*/,
        number: $ => /\d+/,
    },
});

```

